/* Hội thoại (课文) của từng bài — sinh bởi scripts/build-dialogues.py từ scripts/dialogues-h*.txt. Đừng sửa tay. */
window.DIALOGUES = {"h1-01":[{"t":"Bài khóa 1 · Chào hỏi AI Tiểu Ngữ","l":[["王一飞","Wáng Yīfēi","AI小语，你好！","AI Xiǎoyǔ, nǐ hǎo!","Chào AI Tiểu Ngữ!"],["小语","Xiǎoyǔ","王老师，你好！","Wáng lǎoshī, nǐ hǎo!","Chào thầy Vương!"]]},{"t":"Bài khóa 2 · Chào thầy cô và cả lớp","l":[["王一飞","Wáng Yīfēi","大家好！","Dàjiā hǎo!","Chào cả lớp!"],["学生们","xuéshengmen","老师，您好！","Lǎoshī, nín hǎo!","Em chào thầy ạ!"],["小语","Xiǎoyǔ","你们好！","Nǐmen hǎo!","Chào các bạn!"],["学生们","xuéshengmen","你好，小语！","Nǐ hǎo, Xiǎoyǔ!","Chào Tiểu Ngữ!"]]},{"t":"Bài khóa 3 · Cảm ơn và tạm biệt","l":[["学生们","xuéshengmen","谢谢！","Xièxie!","Cảm ơn!"],["小语","Xiǎoyǔ","不客气！","Bú kèqi!","Không có gì!"],["王一飞","Wáng Yīfēi","同学们，再见！","Tóngxuémen, zàijiàn!","Các em, tạm biệt!"],["学生们","xuéshengmen","老师，再见！","Lǎoshī, zàijiàn!","Tạm biệt thầy!"]]}],"h1-02":[{"t":"Bài khóa 1 · Hỏi tên","l":[["王一飞","Wáng Yīfēi","请问，你叫什么名字？","Qǐngwèn, nǐ jiào shénme míngzi?","Xin hỏi, bạn tên là gì?"],["陈天中","Chén Tiānzhōng","我叫陈天中。","Wǒ jiào Chén Tiānzhōng.","Tôi tên là Trần Thiên Trung."]]},{"t":"Bài khóa 2 · Nhận nhầm người","l":[["陈天中","Chén Tiānzhōng","你好，安妮！","Nǐ hǎo, Ānnī!","Chào Annie!"],["白家月","Bái Jiāyuè","你好，陈天中！我不是安妮，我是白家月。","Nǐ hǎo, Chén Tiānzhōng! Wǒ bú shì Ānnī, wǒ shì Bái Jiāyuè.","Chào Trần Thiên Trung! Tôi không phải Annie, tôi là Bạch Gia Nguyệt."],["陈天中","Chén Tiānzhōng","对不起！","Duìbuqǐ!","Xin lỗi!"],["白家月","Bái Jiāyuè","没关系！","Méi guānxi!","Không sao!"]]},{"t":"Bài khóa 3 · Làm quen","l":[["李文","Lǐ Wén","你好，我叫李文！","Nǐ hǎo, wǒ jiào Lǐ Wén!","Chào bạn, tôi tên là Lý Văn!"],["白家月","Bái Jiāyuè","你好，我叫白家月。","Nǐ hǎo, wǒ jiào Bái Jiāyuè.","Chào bạn, tôi tên là Bạch Gia Nguyệt."],["李文","Lǐ Wén","很高兴认识你。","Hěn gāoxìng rènshi nǐ.","Rất vui được làm quen với bạn."],["白家月","Bái Jiāyuè","认识你我也很高兴。","Rènshi nǐ wǒ yě hěn gāoxìng.","Quen bạn tôi cũng rất vui."]]}],"h1-03":[{"t":"Bài khóa 1 · Bạn là người nước nào","l":[["李文","Lǐ Wén","我是中国人。","Wǒ shì Zhōngguórén.","Tôi là người Trung Quốc."],["白家月","Bái Jiāyuè","我是法国人。我的中文老师也是中国人。","Wǒ shì Fǎguórén. Wǒ de Zhōngwén lǎoshī yě shì Zhōngguórén.","Tôi là người Pháp. Cô giáo tiếng Trung của tôi cũng là người Trung Quốc."]]},{"t":"Bài khóa 2 · Đây là ai?","l":[["安妮","Ānnī","这是谁？","Zhè shì shéi?","Đây là ai?"],["陈天中","Chén Tiānzhōng","这是我女朋友。","Zhè shì wǒ nǚpéngyou.","Đây là bạn gái tôi."],["安妮","Ānnī","你女朋友是哪国人？","Nǐ nǚpéngyou shì nǎ guórén?","Bạn gái bạn là người nước nào?"],["陈天中","Chén Tiānzhōng","她也是泰国人。","Tā yě shì Tàiguórén.","Cô ấy cũng là người Thái Lan."]]},{"t":"Bài khóa 3 · Gọi điện cho em trai","l":[["王一雪","Wáng Yīxuě","喂，一飞！","Wèi, Yīfēi!","A lô, Nhất Phi!"],["王一飞","Wáng Yīfēi","姐姐！","Jiějie!","Chị!"],["王一雪","Wáng Yīxuě","你工作还忙吗？","Nǐ gōngzuò hái máng ma?","Công việc của em vẫn bận chứ?"],["王一飞","Wáng Yīfēi","对，还很忙。你也很忙吗？","Duì, hái hěn máng. Nǐ yě hěn máng ma?","Vâng, vẫn rất bận. Chị cũng rất bận ạ?"],["王一雪","Wáng Yīxuě","我不太忙。我们很想你。","Wǒ bú tài máng. Wǒmen hěn xiǎng nǐ.","Chị không bận lắm. Chúng chị rất nhớ em."],["王一飞","Wáng Yīfēi","我也想你们。","Wǒ yě xiǎng nǐmen.","Em cũng nhớ mọi người."]]}],"h1-04":[{"t":"Bài khóa 1 · Hỏi về Nhất Phi","l":[["刘明","Liú Míng","一飞忙吗？","Yīfēi máng ma?","Nhất Phi có bận không?"],["王一雪","Wáng Yīxuě","他很忙。","Tā hěn máng.","Nó rất bận."],["刘明","Liú Míng","他有多少个学生？","Tā yǒu duōshao ge xuésheng?","Nó có bao nhiêu học sinh?"],["王一雪","Wáng Yīxuě","他有二十个学生。","Tā yǒu èr shí ge xuésheng.","Nó có hai mươi học sinh."]]},{"t":"Bài khóa 2 · Gia đình bạn có mấy người","l":[["王一雪","Wáng Yīxuě","我有两个哥哥，你呢？","Wǒ yǒu liǎng ge gēge, nǐ ne?","Tôi có hai anh trai, còn bạn?"],["杨同乐","Yáng Tónglè","我没有哥哥。","Wǒ méiyǒu gēge.","Tôi không có anh trai."],["王一雪","Wáng Yīxuě","你家有几口人？","Nǐ jiā yǒu jǐ kǒu rén?","Nhà bạn có mấy người?"],["杨同乐","Yáng Tónglè","我家有四口人，爸爸、妈妈、妹妹和我。","Wǒ jiā yǒu sì kǒu rén, bàba, māma, mèimei hé wǒ.","Nhà tôi có bốn người: bố, mẹ, em gái và tôi."]]},{"t":"Bài khóa 3 · Hỏi tuổi con","l":[["杨同乐","Yáng Tónglè","您儿子几岁？","Nín érzi jǐ suì?","Con trai chị mấy tuổi rồi?"],["王一雪","Wáng Yīxuě","他今年五岁。","Tā jīnnián wǔ suì.","Cháu năm nay năm tuổi."],["杨同乐","Yáng Tónglè","您女儿多大？","Nín nǚ'ér duō dà?","Con gái chị bao nhiêu tuổi?"],["王一雪","Wáng Yīxuě","她今年十二。","Tā jīnnián shí èr.","Cháu năm nay mười hai."]]}],"h1-05":[{"t":"Bài khóa 1 · Hôm nay ngày mấy?","l":[["王一雪","Wáng Yīxuě","今天几号？","Jīntiān jǐ hào?","Hôm nay là ngày mấy?"],["刘明","Liú Míng","今天九月八号。","Jīntiān jiǔ yuè bā hào.","Hôm nay là ngày 8 tháng 9."],["王一雪","Wáng Yīxuě","星期几？","Xīngqī jǐ?","Thứ mấy?"],["刘明","Liú Míng","星期日。今天我休息。","Xīngqīrì. Jīntiān wǒ xiūxi.","Chủ nhật. Hôm nay anh nghỉ."]]},{"t":"Bài khóa 2 · Biết nấu ăn không?","l":[["王一雪","Wáng Yīxuě","你会做饭吗？","Nǐ huì zuòfàn ma?","Bạn biết nấu cơm không?"],["杨同乐","Yáng Tónglè","我会做。","Wǒ huì zuò.","Tôi biết nấu."],["王一雪","Wáng Yīxuě","你会做什么？","Nǐ huì zuò shénme?","Bạn biết nấu món gì?"],["杨同乐","Yáng Tónglè","我会做面条儿、饺子，也会做一些菜。星期天我也做饭。","Wǒ huì zuò miàntiáor, jiǎozi, yě huì zuò yìxiē cài. Xīngqītiān wǒ yě zuòfàn.","Tôi biết nấu mì, làm sủi cảo, cũng biết nấu vài món. Chủ nhật tôi cũng nấu cơm."]]},{"t":"Bài khóa 3 · Máy tính mới","l":[["王一雪","Wáng Yīxuě","这是你的新电脑吗？","Zhè shì nǐ de xīn diànnǎo ma?","Đây là máy tính mới của bạn à?"],["杨同乐","Yáng Tónglè","是的，是我的新电脑。","Shì de, shì wǒ de xīn diànnǎo.","Vâng, là máy tính mới của tôi."],["王一雪","Wáng Yīxuě","真好看！","Zhēn hǎokàn!","Đẹp thật!"],["杨同乐","Yáng Tónglè","我也很喜欢它。","Wǒ yě hěn xǐhuan tā.","Tôi cũng rất thích nó."]]}],"h1-06":[{"t":"Bài khóa 1 · Số điện thoại","l":[["李文","Lǐ Wén","家月，你的手机号是多少？","Jiāyuè, nǐ de shǒujī hào shì duōshao?","Gia Nguyệt, số điện thoại của bạn là bao nhiêu?"],["白家月","Bái Jiāyuè","我的手机号是加三三，六零一四九三一九零。","Wǒ de shǒujī hào shì jiā sān sān, liù líng yī sì jiǔ sān yī jiǔ líng.","Số điện thoại của tôi là +33 601493190."],["李文","Lǐ Wén","我的手机号是加八六，一三五五二七二一一六零。","Wǒ de shǒujī hào shì jiā bā liù, yì sān wǔ wǔ èr qī èr yī yí liù líng.","Số điện thoại của tôi là +86 13552721160."],["白家月","Bái Jiāyuè","好的。","Hǎo de.","Được rồi."]]},{"t":"Bài khóa 2 · Ngày mai đi đâu?","l":[["陈天中","Chén Tiānzhōng","家月，明天你去哪儿？","Jiāyuè, míngtiān nǐ qù nǎr?","Gia Nguyệt, ngày mai bạn đi đâu?"],["白家月","Bái Jiāyuè","我想去超市买东西。","Wǒ xiǎng qù chāoshì mǎi dōngxi.","Tôi muốn đi siêu thị mua đồ."],["陈天中","Chén Tiānzhōng","你去超市买什么？","Nǐ qù chāoshì mǎi shénme?","Bạn đi siêu thị mua gì?"],["白家月","Bái Jiāyuè","我想买些牛奶。","Wǒ xiǎng mǎi xiē niúnǎi.","Tôi muốn mua ít sữa."]]},{"t":"Bài khóa 3 · Chủ nhật ăn ở đâu?","l":[["王一雪","Wáng Yīxuě","星期天我们去哪儿吃饭？","Xīngqītiān wǒmen qù nǎr chī fàn?","Chủ nhật chúng ta đi đâu ăn cơm?"],["刘明","Liú Míng","我还想去西安饭店。","Wǒ hái xiǎng qù Xī'ān Fàndiàn.","Anh còn muốn đến nhà hàng Tây An."],["刘小雪","Liú Xiǎoxuě","那边的包子非常好吃，我想吃包子。","Nàbiān de bāozi fēicháng hǎochī, wǒ xiǎng chī bāozi.","Bánh bao bên kia rất ngon, con muốn ăn bánh bao."],["刘小明","Liú Xiǎomíng","妈妈，我想吃米饭，不想吃包子。","Māma, wǒ xiǎng chī mǐfàn, bù xiǎng chī bāozi.","Mẹ ơi, con muốn ăn cơm, không muốn ăn bánh bao."],["王一雪","Wáng Yīxuě","好的。我们怎么去？","Hǎo de. Wǒmen zěnme qù?","Được rồi. Chúng ta đi bằng gì?"],["刘明","Liú Míng","坐出租车去。","Zuò chūzūchē qù.","Đi taxi."]]}],"h1-07":[{"t":"Bài khóa 1 · Mấy giờ rồi?","l":[["白家月","Bái Jiāyuè","现在几点？","Xiànzài jǐ diǎn?","Bây giờ mấy giờ?"],["安妮","Ānnī","早上八点四十。","Zǎoshang bā diǎn sì shí.","Tám giờ bốn mươi sáng."],["白家月","Bái Jiāyuè","我上午十点十分有课。","Wǒ shàngwǔ shí diǎn shí fēn yǒu kè.","Mười giờ mười sáng tôi có tiết học."],["安妮","Ānnī","老师，再见！","Lǎoshī, zàijiàn!","Cô ơi, tạm biệt!"]]},{"t":"Bài khóa 2 · Rủ đi xem phim","l":[["李文","Lǐ Wén","下午我想去电影院看电影，你去吗？","Xiàwǔ wǒ xiǎng qù diànyǐngyuàn kàn diànyǐng, nǐ qù ma?","Chiều nay tôi muốn đi rạp xem phim, bạn đi không?"],["白家月","Bái Jiāyuè","我不想去，下午还有事。","Wǒ bù xiǎng qù, xiàwǔ hái yǒu shì.","Tôi không muốn đi, chiều còn có việc."],["李文","Lǐ Wén","好的。明天呢？","Hǎo de. Míngtiān ne?","Được rồi. Thế ngày mai thì sao?"],["白家月","Bái Jiāyuè","我明天下午两点还上课呢，四点半下课。","Wǒ míngtiān xiàwǔ liǎng diǎn hái shàngkè ne, sì diǎn bàn xià kè.","Chiều mai hai giờ tôi còn có tiết, bốn rưỡi mới tan."]]},{"t":"Bài khóa 3 · Gọi điện về nhà","l":[["王一雪","Wáng Yīxuě","喂，你在哪儿呢？","Wèi, nǐ zài nǎr ne?","A lô, anh đang ở đâu đấy?"],["刘明","Liú Míng","我在家里呢。","Wǒ zài jiā lǐ ne.","Anh đang ở nhà."],["王一雪","Wáng Yīxuě","我晚上六点半下班。","Wǒ wǎnshang liù diǎn bàn xiàbān.","Sáu rưỡi tối em tan làm."],["刘明","Liú Míng","我八点去医院上班。","Wǒ bā diǎn qù yīyuàn shàng bān.","Tám giờ anh đến bệnh viện đi làm."],["王一雪","Wáng Yīxuě","好的，你去店里买些菜吧。","Hǎo de, nǐ qù diàn lǐ mǎi xiē cài ba.","Được, anh ra tiệm mua ít rau đi."],["刘明","Liú Míng","好，我十分钟后去。","Hǎo, wǒ shí fēn zhōng hòu qù.","Được, mười phút nữa anh đi."]]}],"h1-08":[{"t":"Bài khóa 1 · Chú mèo con","l":[["白家月","Bái Jiāyuè","房间外有一只小猫。","Fángjiān wài yǒu yì zhī xiǎo māo.","Ngoài phòng có một chú mèo con."],["陈天中","Chén Tiānzhōng","我没看见，它在哪儿呢？","Wǒ méi kànjiàn, tā zài nǎr ne?","Tôi không thấy, nó ở đâu vậy?"],["白家月","Bái Jiāyuè","它在桌子下呢。","Tā zài zhuōzi xià ne.","Nó ở dưới bàn kìa."],["陈天中","Chén Tiānzhōng","这只小猫真漂亮！","Zhè zhī xiǎo māo zhēn piàoliang!","Chú mèo này đẹp thật!"]]},{"t":"Bài khóa 2 · Hẹn gặp ở đâu?","l":[["白家月","Bái Jiāyuè","我们在哪儿见呢？","Wǒmen zài nǎr jiàn ne?","Chúng ta gặp nhau ở đâu nhỉ?"],["李文","Lǐ Wén","在学校书店前见吧。","Zài xuéxiào shūdiàn qián jiàn ba.","Gặp nhau trước hiệu sách của trường nhé."],["白家月","Bái Jiāyuè","好的。下午两点你能到吗？","Hǎo de. Xiàwǔ liǎng diǎn nǐ néng dào ma?","Được. Hai giờ chiều bạn đến được không?"],["李文","Lǐ Wén","我能到。我在学校吃午饭。","Wǒ néng dào. Wǒ zài xuéxiào chī wǔfàn.","Tôi đến được. Tôi ăn trưa ở trường."]]}],"h1-09":[{"t":"Bài khóa 1 · Hẹn xem phim buổi tối","l":[["白家月","Bái Jiāyuè","学校前边有一家电影院。","Xuéxiào qiánbian yǒu yì jiā diànyǐngyuàn.","Phía trước trường có một rạp chiếu phim."],["李文","Lǐ Wén","对。我们晚上去那个电影院看电影吧。","Duì. Wǒmen wǎnshang qù nàge diànyǐngyuàn kàn diànyǐng ba.","Đúng. Tối nay chúng ta đến rạp đó xem phim nhé."],["白家月","Bái Jiāyuè","对！我们七点在电影院外边见，好吗？","Duì! Wǒmen qī diǎn zài diànyǐngyuàn wàibian jiàn, hǎo ma?","Được! Bảy giờ gặp nhau bên ngoài rạp, được không?"],["李文","Lǐ Wén","好的，晚上七点见！","Hǎo de, wǎnshang qī diǎn jiàn!","Được, bảy giờ tối gặp nhé!"]]},{"t":"Bài khóa 2 · Quyển sách tiếng Trung","l":[["白家月","Bái Jiāyuè","椅子上有一本中文书，那是谁的书？","Yǐzi shàng yǒu yì běn Zhōngwén shū, nà shì shéi de shū?","Trên ghế có một quyển sách tiếng Trung, đó là sách của ai vậy?"],["陈天中","Chén Tiānzhōng","是我的书，谢谢。这是我的第二本中文书。","Shì wǒ de shū, xièxie. Zhè shì wǒ de dì èr běn Zhōngwén shū.","Là sách của tôi, cảm ơn. Đây là quyển sách tiếng Trung thứ hai của tôi."],["白家月","Bái Jiāyuè","不客气。你明天上午在哪儿？","Bú kèqi. Nǐ míngtiān shàngwǔ zài nǎr?","Không có gì. Sáng mai bạn ở đâu?"],["陈天中","Chén Tiānzhōng","我明天上午在学校学习。","Wǒ míngtiān shàngwǔ zài xuéxiào xuéxí.","Sáng mai tôi học ở trường."]]},{"t":"Bài khóa 3 · Cuối tuần làm gì?","l":[["王一雪","Wáng Yīxuě","你唱歌很好听。","Nǐ chànggē hěn hǎotīng.","Bạn hát hay lắm."],["杨同乐","Yáng Tónglè","谢谢！你星期六做什么？","Xièxie! Nǐ xīngqīliù zuò shénme?","Cảm ơn! Thứ Bảy bạn làm gì?"],["王一雪","Wáng Yīxuě","我在家里做饭、看电视，和孩子们、小狗玩。","Wǒ zài jiā lǐ zuòfàn, kàn diànshì, hé háizimen, xiǎo gǒu wán.","Tôi ở nhà nấu cơm, xem ti vi, chơi với các con và chú chó."],["杨同乐","Yáng Tónglè","我也有一只小狗。","Wǒ yě yǒu yì zhī xiǎo gǒu.","Tôi cũng có một chú chó."]]}],"h1-10":[{"t":"Bài khóa 1 · Mua cốc","l":[["王一雪","Wáng Yīxuě","请问，有杯子吗？","Qǐngwèn, yǒu bēizi ma?","Xin hỏi, có cốc không ạ?"],["售货员","Shòuhuòyuán","有，杯子在这边。","Yǒu, bēizi zài zhè biān.","Có, cốc ở bên này."],["王一雪","Wáng Yīxuě","多少钱一个？","Duōshao qián yí ge?","Bao nhiêu tiền một cái?"],["售货员","Shòuhuòyuán","这些五块钱一个，那些十块钱一个。","Zhèxiē wǔ kuài qián yí ge, nàxiē shí kuài qián yí ge.","Những cái này năm tệ một cái, những cái kia mười tệ một cái."],["王一雪","Wáng Yīxuě","我买这个吧。","Wǒ mǎi zhège ba.","Tôi mua cái này vậy."]]},{"t":"Bài khóa 2 · Mua trái cây","l":[["王一雪","Wáng Yīxuě","这儿的水果真不少。","Zhèr de shuǐguǒ zhēn bù shǎo.","Trái cây ở đây nhiều thật."],["售货员","Shòuhuòyuán","您想买什么？","Nín xiǎng mǎi shénme?","Chị muốn mua gì?"],["王一雪","Wáng Yīxuě","我想买两斤苹果。","Wǒ xiǎng mǎi liǎng jīn píngguǒ.","Tôi muốn mua hai cân táo."],["售货员","Shòuhuòyuán","苹果三块五一斤，这些七块二，七块钱吧。","Píngguǒ sān kuài wǔ yī jīn, zhèxiē qī kuài èr, qī kuài qián ba.","Táo ba tệ rưỡi một cân, chỗ này bảy tệ hai, tính bảy tệ nhé."],["王一雪","Wáng Yīxuě","好的，这儿的苹果真便宜。","Hǎo de, zhèr de píngguǒ zhēn piányi.","Được, táo ở đây rẻ thật."]]},{"t":"Bài khóa 3 · Mua quần áo","l":[["王一雪","Wáng Yīxuě","这家商店衣服真多，这件一百元，怎么样？","Zhè jiā shāngdiàn yīfu zhēn duō, zhè jiàn yì bǎi yuán, zěnmeyàng?","Cửa hàng này nhiều quần áo thật, chiếc này một trăm tệ, anh thấy sao?"],["刘明","Liú Míng","好看，也不贵。","Hǎokàn, yě bú guì.","Đẹp, cũng không đắt."],["王一雪","Wáng Yīxuě","小雪能穿，买一件吧。","Xiǎoxuě néng chuān, mǎi yí jiàn ba.","Tiểu Tuyết mặc được, mua một chiếc đi."],["刘明","Liú Míng","好的，小明能穿吗？","Hǎo de, Xiǎomíng néng chuān ma?","Được, Tiểu Minh mặc được không?"],["王一雪","Wáng Yīxuě","不能，这些是女孩子的衣服，男孩子的衣服在那儿。","Bù néng, zhèxiē shì nǚháizi de yīfu, nánháizi de yīfu zài nàr.","Không được, đây là quần áo con gái, quần áo con trai ở đằng kia."],["刘明","Liú Míng","好的。","Hǎo de.","Được."]]}],"h1-11":[{"t":"Bài khóa 1 · Tìm nhà hàng","l":[["王一飞","Wáng Yīfēi","喂，李文，你什么时候能到饭店？","Wèi, Lǐ Wén, nǐ shénme shíhou néng dào fàndiàn?","A lô, Lý Văn, khi nào bạn đến được nhà hàng?"],["李文","Lǐ Wén","还不知道，正在找呢。它是不是在超市后边？","Hái bù zhīdào, zhèngzài zhǎo ne. Tā shì bu shì zài chāoshì hòu biān?","Chưa biết, đang tìm đây. Có phải nó ở phía sau siêu thị không?"],["王一飞","Wáng Yīfēi","是的。你开车没开车？","Shì de. Nǐ kāichē méi kāichē?","Đúng vậy. Bạn có lái xe không?"],["李文","Lǐ Wén","我没开车，坐车呢。","Wǒ méi kāichē, zuò chē ne.","Tôi không lái xe, đang đi xe đây."]]},{"t":"Bài khóa 2 · Còn đang học đại học","l":[["王一飞","Wáng Yīfēi","你还在读大学吗？","Nǐ hái zài dú dàxué ma?","Bạn vẫn đang học đại học à?"],["李文","Lǐ Wén","对，我读大学呢，还是大学生。","Duì, wǒ dú dàxué ne, háishi dàxuéshēng.","Đúng, tôi đang học đại học, vẫn là sinh viên."],["王一飞","Wáng Yīfēi","你们学习忙不忙？","Nǐmen xuéxí máng bu máng?","Các bạn học có bận không?"],["李文","Lǐ Wén","非常忙，我学医，我们的课很多。","Fēicháng máng, wǒ xué yī, wǒmen de kè hěn duō.","Rất bận, tôi học y, bọn tôi có rất nhiều tiết."]]},{"t":"Bài khóa 3 · Con trai đi đâu?","l":[["刘明","Liú Míng","还睡呢？他今天去不去那里？","Hái shuì ne? Tā jīntiān qù bu qù nàlǐ?","Vẫn đang ngủ à? Hôm nay nó có đến đó không?"],["刘小雪","Liú Xiǎoxuě","去哪里？","Qù nǎ lǐ?","Đi đâu ạ?"],["刘明","Liú Míng","去超市。","Qù chāoshì.","Đi siêu thị."],["刘小雪","Liú Xiǎoxuě","我昨天问他，他对我说，他不去，他今天要和小朋友玩。","Wǒ zuótiān wèn tā, tā duì wǒ shuō, tā bú qù, tā jīntiān yào hé xiǎo péngyou wán.","Hôm qua con hỏi em, em nói với con là em không đi, hôm nay em sẽ chơi với các bạn nhỏ."]]}],"h1-12":[{"t":"Bài khóa 1 · Thời tiết hôm nay","l":[["王一雪","Wáng Yīxuě","今天天气怎么样？","Jīntiān tiānqì zěnmeyàng?","Hôm nay thời tiết thế nào?"],["王一飞","Wáng Yīfēi","这里的天不太好，下雨了。","Zhèlǐ de tiān bú tài hǎo, xiàyǔ le.","Trời ở đây không tốt lắm, mưa rồi."],["王一雪","Wáng Yīxuě","雨大吗？","Yǔ dà ma?","Mưa có to không?"],["王一飞","Wáng Yīfēi","有点儿大，我觉得很冷。","Yǒudiǎnr dà, wǒ juéde hěn lěng.","Hơi to, em thấy rất lạnh."]]},{"t":"Bài khóa 2 · Hôm qua nghỉ làm","l":[["王一雪","Wáng Yīxuě","昨天下雪了。","Zuótiān xiàxuě le.","Hôm qua có tuyết rơi."],["杨同乐","Yáng Tónglè","是的，太冷了。","Shì de, tài lěng le.","Đúng vậy, lạnh quá."],["王一雪","Wáng Yīxuě","你昨天没来公司，生病了？","Nǐ zuótiān méi lái gōngsī, shēngbìng le?","Hôm qua bạn không đến công ty, bị ốm à?"],["杨同乐","Yáng Tónglè","对，我昨天去医院看病了。","Duì, wǒ zuótiān qù yīyuàn kàn bìng le.","Vâng, hôm qua tôi đi bệnh viện khám bệnh."]]}],"h1-13":[{"t":"Bài khóa 1 · Hỏi thầy một câu","l":[["白家月","Bái Jiāyuè","王老师，我可以再问您一个问题吗？","Wáng lǎoshī, wǒ kěyǐ zài wèn nín yí ge wèntí ma?","Thầy Vương, em có thể hỏi thầy thêm một câu được không ạ?"],["王一飞","Wáng Yīfēi","可以，你有什么问题？","Kěyǐ, nǐ yǒu shénme wèntí?","Được, em có câu hỏi gì?"],["白家月","Bái Jiāyuè","那个小店卖不卖手机？","Nàge xiǎo diàn mài bu mài shǒujī?","Cửa tiệm nhỏ kia có bán điện thoại không ạ?"],["王一飞","Wáng Yīfēi","我不知道。你可以打电话问一下。","Wǒ bù zhīdào. Nǐ kěyǐ dǎ diànhuà wèn yíxià.","Thầy không biết. Em có thể gọi điện hỏi thử."]]},{"t":"Bài khóa 2 · Gọi đồ ở quán","l":[["服务员","Fúwùyuán","女士，请坐！您喝什么？","Nǚshì, qǐng zuò! Nín hē shénme?","Mời chị ngồi! Chị uống gì ạ?"],["王一雪","Wáng Yīxuě","我看一下。请给我一杯牛奶。","Wǒ kàn yíxià. Qǐng gěi wǒ yì bēi niúnǎi.","Để tôi xem. Cho tôi một ly sữa."],["服务员","Fúwùyuán","好的。您还要什么？","Hǎo de. Nín hái yào shénme?","Vâng. Chị còn dùng gì nữa không?"],["王一雪","Wáng Yīxuě","我还没吃早饭，再要这个面包和鸡蛋吧。","Wǒ hái méi chī zǎofàn, zài yào zhège miànbāo hé jīdàn ba.","Tôi chưa ăn sáng, cho thêm bánh mì và trứng này nhé."]]}],"h1-14":[{"t":"Bài khóa 1 · Trên chuyến tàu","l":[["白家月","Bái Jiāyuè","你们上火车后看见王老师了吗？","Nǐmen shàng huǒchē hòu kànjiàn Wáng lǎoshī le ma?","Sau khi lên tàu các bạn có thấy thầy Vương không?"],["陈天中","Chén Tiānzhōng","没看见。中午车开后，有些人在看书，有些人睡觉了。","Méi kànjiàn. Zhōngwǔ chē kāi hòu, yǒuxiē rén zài kàn shū, yǒuxiē rén shuìjiào le.","Không thấy. Sau khi tàu chạy lúc trưa, có người đọc sách, có người đi ngủ."],["白家月","Bái Jiāyuè","你呢？","Nǐ ne?","Còn bạn?"],["陈天中","Chén Tiānzhōng","我看了一个电影。","Wǒ kàn le yí ge diànyǐng.","Tôi đã xem một bộ phim."]]},{"t":"Bài khóa 2 · Biết viết chữ Hán chưa?","l":[["王一飞","Wáng Yīfēi","你们会说汉语了，也会写汉字了吗？","Nǐmen huì shuō Hànyǔ le, yě huì xiě Hànzì le ma?","Các em đã biết nói tiếng Hán, cũng đã biết viết chữ Hán chưa?"],["白家月","Bái Jiāyuè","我们都会写了。","Wǒmen dōu huì xiě le.","Chúng em đều biết viết rồi ạ."],["陈天中","Chén Tiānzhōng","老师，我听不见。","Lǎoshī, wǒ tīng bú jiàn.","Thầy ơi, em nghe không thấy."],["王一飞","Wáng Yīfēi","请大家不要说话！请听老师的问题：你们都会写哪些汉字了？","Qǐng dàjiā bú yào shuō huà! Qǐng tīng lǎoshī de wèntí: nǐmen dōu huì xiě nǎ xiē Hànzì le?","Mọi người đừng nói chuyện! Hãy nghe câu hỏi của thầy: các em đã biết viết những chữ Hán nào?"],["陈天中","Chén Tiānzhōng","老师，我听不见。","Lǎoshī, wǒ tīng bú jiàn.","Thầy ơi, em nghe không thấy."]]},{"t":"Bài khóa 3 · Con đã lớn","l":[["刘明","Liú Míng","我们家有了一个中学生。","Wǒmen jiā yǒu le yí ge zhōngxué shēng.","Nhà mình đã có một học sinh cấp hai."],["王一雪","Wáng Yīxuě","还有了一个小学生。","Hái yǒu le yí ge xiǎoxué shēng.","Còn có thêm một học sinh tiểu học."],["刘明","Liú Míng","上学后，他们都忙了。","Shàngxué hòu, tāmen dōu máng le.","Đi học rồi, các con đều bận hơn."],["王一雪","Wáng Yīxuě","是的。太晚了，睡觉吧。","Shì de. Tài wǎn le, shuìjiào ba.","Đúng vậy. Muộn quá rồi, đi ngủ thôi."]]}],"h1-15":[{"t":"Bài khóa 1 · Bữa cơm với bạn bè","l":[["白家月","Bái Jiāyuè","你们爱吃哪个菜？","Nǐmen ài chī nǎge cài?","Các bạn thích ăn món nào?"],["李文","Lǐ Wén","我喜欢这个，也喜欢那个。","Wǒ xǐhuan zhège, yě xǐhuan nàge.","Tôi thích món này, cũng thích món kia."],["李文","Lǐ Wén","这些菜都好吃，还很好看。","Zhèxiē cài dōu hǎochī, hái hěn hǎokàn.","Những món này đều ngon, lại còn đẹp mắt."],["陈天中","Chén Tiānzhōng","我爱吃中国菜，也喜欢做。大家多吃点儿。","Wǒ ài chī Zhōngguó cài, yě xǐhuan zuò. Dàjiā duō chī diǎnr.","Tôi thích ăn món Trung Quốc, cũng thích nấu. Mọi người ăn nhiều vào nhé."]]},{"t":"Bài khóa 2 · Đi du lịch đâu?","l":[["李文","Lǐ Wén","你们都想去哪儿？","Nǐmen dōu xiǎng qù nǎr?","Các bạn đều muốn đi đâu?"],["白家月","Bái Jiāyuè","去年我和男朋友去了西安，今年我想去北京。","Qùnián wǒ hé nánpéngyou qù le Xī'ān, jīnnián wǒ xiǎng qù Běijīng.","Năm ngoái tôi cùng bạn trai đi Tây An, năm nay tôi muốn đi Bắc Kinh."],["安妮","Ānnī","前几年我去了西安，非常好玩儿。今年我也想去北京。","Qián jǐ nián wǒ qù le Xī'ān, fēicháng hǎowánr. Jīnnián wǒ yě xiǎng qù Běijīng.","Mấy năm trước tôi đã đi Tây An, rất vui. Năm nay tôi cũng muốn đi Bắc Kinh."],["李文","Lǐ Wén","我和王老师都是北京人，北京非常漂亮。","Wǒ hé Wáng lǎoshī dōu shì Běijīngrén, Běijīng fēicháng piàoliang.","Tôi và thầy Vương đều là người Bắc Kinh, Bắc Kinh rất đẹp."]]},{"t":"Bài khóa 3 · Hẹn gặp ở sân bay Đại Hưng","l":[["王一飞","Wáng Yīfēi","你们的飞机到北京要几个小时？","Nǐmen de fēijī dào Běijīng yào jǐ ge xiǎoshí?","Máy bay của các em đến Bắc Kinh mất mấy tiếng?"],["白家月","Bái Jiāyuè","九个小时。","Jiǔ ge xiǎoshí.","Chín tiếng."],["白家月","Bái Jiāyuè","我们星期日早上八点到大兴机场，早不早？","Wǒmen xīngqīrì zǎoshang bā diǎn dào Dàxīng Jīchǎng, zǎo bu zǎo?","Chủ nhật tám giờ sáng chúng em đến sân bay Đại Hưng, có sớm không ạ?"],["王一飞","Wáng Yīfēi","不早。我家人都在北京，星期天我姐姐也有时间，她可以去机场接你们，你们也可以住我家。","Bù zǎo. Wǒ jiārén dōu zài Běijīng, xīngqītiān wǒ jiějie yě yǒushí jiān, tā kěyǐ qù jīchǎng jiē nǐmen, nǐmen yě kěyǐ zhù wǒ jiā.","Không sớm. Người nhà thầy đều ở Bắc Kinh, Chủ nhật chị thầy cũng rảnh, chị có thể ra sân bay đón các em, các em cũng có thể ở nhà thầy."],["安妮","Ānnī","谢谢老师！那我们和您姐姐在大兴机场见！","Xièxie lǎoshī! Nà wǒmen hé nín jiějie zài Dàxīng Jīchǎng jiàn!","Cảm ơn thầy! Vậy chúng em hẹn gặp chị của thầy ở sân bay Đại Hưng!"]]}],"h2-01":[{"t":"Bài khóa 1 · Đón ở sân bay","l":[["白家月","Bái Jiāyuè","请问，您是王一飞老师的姐姐吗？","Qǐngwèn, nín shì Wáng Yīfēi lǎoshī de jiějie ma?","Xin hỏi, chị có phải là chị của thầy Vương Nhất Phi không ạ?"],["王一雪","Wáng Yīxuě","是的，你们就是她的学生吧？","Shì de, nǐmen jiù shì tā de xuésheng ba?","Đúng vậy, các em là học sinh của nó phải không?"],["白家月","Bái Jiāyuè","对。我是白家月，她是安妮。","Duì. Wǒ shì Bái Jiāyuè, tā shì Ānnī.","Vâng. Em là Bạch Gia Nguyệt, bạn ấy là Annie."],["王一雪","Wáng Yīxuě","你们好，我叫王一雪。一飞给我打电话了，让我来接你们。","Nǐmen hǎo, wǒ jiào Wáng Yīxuě. Yīfēi gěi wǒ dǎ diànhuà le, ràng wǒ lái jiē nǐmen.","Chào các em, chị tên là Vương Nhất Tuyết. Nhất Phi đã gọi điện cho chị, nhờ chị đến đón các em."],["白家月","Bái Jiāyuè","谢谢您。","Xièxie nín.","Cảm ơn chị ạ."],["王一雪","Wáng Yīxuě","不客气。","Bú kèqi.","Không có gì."]]},{"t":"Bài khóa 2 · Lần đầu đến Bắc Kinh","l":[["王一雪","Wáng Yīxuě","你们是第一次来北京吗？","Nǐmen shì dì yī cì lái Běijīng ma?","Các em lần đầu đến Bắc Kinh à?"],["白家月","Bái Jiāyuè","是的，我们都是第一次来。","Shì de, wǒmen dōu shì dì yī cì lái.","Vâng, chúng em đều là lần đầu đến."],["王一雪","Wáng Yīxuě","你们是来学中文的吗？","Nǐmen shì lái xué Zhōngwén de ma?","Các em đến để học tiếng Trung à?"],["安妮","Ānnī","不是，我们是来旅游的。","Bú shì, wǒmen shì lái lǚyóu de.","Không ạ, chúng em đến du lịch."],["王一雪","Wáng Yīxuě","我这几天都不忙，你们有事就找我。","Wǒ zhè jǐ tiān dōu bù máng, nǐmen yǒu shì jiù zhǎo wǒ.","Mấy ngày nay chị đều không bận, các em có việc gì cứ tìm chị."],["白家月","Bái Jiāyuè","好的，谢谢您。","Hǎo de, xièxie nín.","Vâng, cảm ơn chị."]]},{"t":"Bài khóa 3 · Nhờ Lý Văn giúp","l":[["陈天中","Chén Tiānzhōng","喂，家月，你明天有时间吗？我想请你帮个忙。","Wèi, Jiāyuè, nǐ míngtiān yǒushí jiān ma? Wǒ xiǎng qǐng nǐ bāng ge máng.","A lô, Gia Nguyệt, ngày mai bạn có thời gian không? Tôi muốn nhờ bạn một việc."],["白家月","Bái Jiāyuè","不好意思，天中，我已经到北京了。","Bù hǎo yìsi, Tiānzhōng, wǒ yǐjīng dào Běijīng le.","Xin lỗi Thiên Trung, tôi đã đến Bắc Kinh rồi."],["陈天中","Chén Tiānzhōng","你是什么时候到的？","Nǐ shì shénme shíhou dào de?","Bạn đến từ khi nào vậy?"],["白家月","Bái Jiāyuè","我是今天早上到的。你有事可以叫李文帮忙，他还在学校呢。","Wǒ shì jīntiān zǎoshang dào de. Nǐ yǒu shì kěyǐ jiào Lǐ Wén bāngmáng, tā hái zài xuéxiào ne.","Tôi đến sáng nay. Bạn có việc thì có thể nhờ Lý Văn giúp, cậu ấy vẫn còn ở trường."],["陈天中","Chén Tiānzhōng","好的，那我给他打个电话。","Hǎo de, nà wǒ gěi tā dǎ ge diànhuà.","Được, vậy tôi gọi điện cho cậu ấy."],["白家月","Bái Jiāyuè","好，再见！","Hǎo, zàijiàn!","Được, tạm biệt!"]]}],"h2-02":[{"t":"Bài khóa 1 · Hỏi đường đến Đại học Bắc Kinh","l":[["白家月","Bái Jiāyuè","请问，这儿有到北京大学的公交车吗？","Qǐngwèn, zhèr yǒu dào Běijīng Dàxué de gōngjiāochē ma?","Xin hỏi, ở đây có xe buýt đến Đại học Bắc Kinh không?"],["服务员","Fúwùyuán","有，但车站有点儿远。","Yǒu, dàn chēzhàn yǒudiǎnr yuǎn.","Có, nhưng trạm xe hơi xa một chút."],["白家月","Bái Jiāyuè","这儿好打车吗？","Zhèr hǎo dǎchē ma?","Ở đây có dễ bắt taxi không?"],["服务员","Fúwùyuán","好打车。","Hǎo dǎchē.","Dễ bắt."],["白家月","Bái Jiāyuè","谢谢。安妮，我们还是打车去吧。","Xièxie. Ānnī, wǒmen háishi dǎchē qù ba.","Cảm ơn. Annie, chúng ta vẫn nên đi taxi nhé."],["安妮","Ānnī","好，没问题。","Hǎo, méi wèntí.","Được, không vấn đề gì."]]},{"t":"Bài khóa 2 · Trong khuôn viên trường","l":[["白家月","Bái Jiāyuè","学校里人真多啊！","Xuéxiào lǐ rén zhēn duō a!","Trong trường đông người thật!"],["安妮","Ānnī","是啊，北京大学有四万多名学生呢！","Shì a, Běijīng Dàxué yǒu sì wàn duō míng xuésheng ne!","Đúng vậy, Đại học Bắc Kinh có hơn bốn vạn sinh viên cơ đấy!"],["白家月","Bái Jiāyuè","你是怎么知道的？","Nǐ shì zěnme zhīdào de?","Sao bạn biết vậy?"],["安妮","Ānnī","是网上说的，网上还说北京大学有三千多名外国学生。","Shì wǎngshàng shuō de, wǎngshàng hái shuō Běijīng Dàxué yǒu sān qiān duō míng wàiguó xuésheng.","Trên mạng nói đấy, trên mạng còn nói Đại học Bắc Kinh có hơn ba nghìn sinh viên nước ngoài."],["白家月","Bái Jiāyuè","我也想来这儿学习。","Wǒ yě xiǎng lái zhèr xuéxí.","Tôi cũng muốn đến đây học."],["安妮","Ānnī","那边就有一间教室，我们去看一下吧。","Nàbiān jiù yǒu yì jiān jiàoshì, wǒmen qù kàn yíxià ba.","Bên kia có một phòng học, chúng ta đến xem thử đi."]]},{"t":"Bài khóa 3 · Rạp chiếu phim trong trường","l":[["安妮","Ānnī","家月，你看，学校里有家电影院呢！","Jiāyuè, nǐ kàn, xuéxiào lǐ yǒu jiā diànyǐngyuàn ne!","Gia Nguyệt, bạn xem, trong trường có cả rạp chiếu phim kìa!"],["白家月","Bái Jiāyuè","是啊，电影院还不小。","Shì a, diànyǐngyuàn hái bù xiǎo.","Đúng vậy, rạp còn không nhỏ nữa."],["安妮","Ānnī","他们卖的电影票也很便宜。","Tāmen mài de diànyǐng piào yě hěn piányi.","Vé xem phim họ bán cũng rất rẻ."],["白家月","Bái Jiāyuè","天啊！有的还不到二十块钱。","Tiān a! Yǒu de hái bú dào èr shí kuài qián.","Trời ơi! Có vé còn chưa đến hai mươi tệ."],["安妮","Ānnī","那你想不想去看个电影？","Nà nǐ xiǎng bu xiǎng qù kàn ge diànyǐng?","Vậy bạn có muốn đi xem phim không?"],["白家月","Bái Jiāyuè","还是别看电影了，北京大学就很好看！","Háishi bié kàn diànyǐng le, Běijīng Dàxué jiù hěn hǎokàn!","Thôi đừng xem phim nữa, bản thân Đại học Bắc Kinh đã rất đẹp rồi!"]]}],"h2-03":[{"t":"Bài khóa 1 · Về nhà muộn","l":[["王一雪","Wáng Yīxuě","今天回来这么晚啊！","Jīntiān huílái zhème wǎn a!","Hôm nay về muộn thế!"],["刘明","Liú Míng","工作太多了，下班的时候没做完。","Gōngzuò tài duō le, xiàbān de shíhou méi zuòwán.","Việc nhiều quá, lúc tan làm vẫn chưa làm xong."],["王一雪","Wáng Yīxuě","菜都做好了，过来吃饭吧。","Cài dōu zuò hǎo le, guò lái chī fàn ba.","Thức ăn nấu xong cả rồi, lại ăn cơm đi."],["刘明","Liú Míng","我想休息一下，喝杯水。","Wǒ xiǎng xiūxi yíxià, hē bēi shuǐ.","Anh muốn nghỉ một chút, uống cốc nước."],["王一雪","Wáng Yīxuě","好的。","Hǎo de.","Được."]]},{"t":"Bài khóa 2 · Bàn chuyện đi du lịch","l":[["刘明","Liú Míng","我们找个时间去旅游，怎么样？","Wǒmen zhǎo ge shíjiān qù lǚyóu, zěnmeyàng?","Chúng mình tìm thời gian đi du lịch, em thấy sao?"],["王一雪","Wáng Yīxuě","好啊，我也很想一起出去玩。","Hǎo a, wǒ yě hěn xiǎng yìqǐ chū qù wán.","Hay đấy, em cũng rất muốn cùng đi chơi."],["刘明","Liú Míng","你想去哪儿？","Nǐ xiǎng qù nǎr?","Em muốn đi đâu?"],["王一雪","Wáng Yīxuě","我还没想好呢。","Wǒ hái méi xiǎnghǎo ne.","Em vẫn chưa nghĩ ra."],["刘明","Liú Míng","那你再想一想，你想好了，我来买票。","Nà nǐ zài xiǎng yì xiǎng, nǐ xiǎnghǎo le, wǒ lái mǎipiào.","Vậy em nghĩ thêm đi, nghĩ xong anh sẽ mua vé."]]},{"t":"Bài khóa 3 · Vì sao muốn đi Tây An?","l":[["刘明","Liú Míng","吃个苹果吧，我都洗好了。","Chī ge píngguǒ ba, wǒ dōu xǐ hǎo le.","Ăn quả táo đi, anh rửa xong cả rồi."],["王一雪","Wáng Yīxuě","好的。","Hǎo de.","Vâng."],["刘明","Liú Míng","就在桌子上，你自己拿。","Jiù zài zhuōzi shàng, nǐ zìjǐ ná.","Ở ngay trên bàn, em tự lấy nhé."],["王一雪","Wáng Yīxuě","我去洗洗手。对了，我们去西安旅游，怎么样？","Wǒ qù xǐxi shǒu. Duì le, wǒmen qù Xī'ān lǚyóu, zěnmeyàng?","Em đi rửa tay đã. À này, chúng mình đi Tây An du lịch, anh thấy sao?"],["刘明","Liú Míng","为什么想去西安？","Wèishénme xiǎng qù Xī'ān?","Vì sao em muốn đi Tây An?"],["王一雪","Wáng Yīxuě","我看了看网上的介绍，这个时候去西安很不错。","Wǒ kàn le kàn wǎngshàng de jièshào, zhège shíhou qù Xī'ān hěn bú cuò.","Em xem giới thiệu trên mạng, lúc này đi Tây An rất tuyệt."]]}],"h2-04":[{"t":"Bài khóa 1 · Đi dạo trung tâm thương mại","l":[["刘小雪","Liú Xiǎoxuě","妈妈，我们来过这家商场吗？","Māma, wǒmen lái guo zhè jiā shāngchǎng ma?","Mẹ ơi, chúng ta đã đến trung tâm thương mại này chưa?"],["王一雪","Wáng Yīxuě","没来过，这是新开的。","Méi lái guo, zhè shì xīn kāi de.","Chưa đến, đây mới mở."],["刘小雪","Liú Xiǎoxuě","我们进去看看吧。","Wǒmen jìnqù kànkan ba.","Chúng ta vào xem thử đi."],["王一雪","Wáng Yīxuě","好啊！你想买点儿什么？","Hǎo a! Nǐ xiǎng mǎi diǎnr shénme?","Được thôi! Con muốn mua gì?"],["刘小雪","Liú Xiǎoxuě","我想买条裤子。","Wǒ xiǎng mǎi tiáo kùzi.","Con muốn mua một chiếc quần."],["王一雪","Wáng Yīxuě","没问题。","Méi wèntí.","Không vấn đề gì."]]},{"t":"Bài khóa 2 · Chọn quần","l":[["刘小雪","Liú Xiǎoxuě","妈妈，我想买这条白色的裤子。","Māma, wǒ xiǎng mǎi zhè tiáo báisè de kùzi.","Mẹ ơi, con muốn mua chiếc quần màu trắng này."],["王一雪","Wáng Yīxuě","你有很多白色的衣服，为什么还买白色的？","Nǐ yǒu hěn duō báisè de yīfu, wèishénme hái mǎi báisè de?","Con có rất nhiều quần áo màu trắng, sao còn mua màu trắng?"],["刘小雪","Liú Xiǎoxuě","因为我喜欢白色啊！","Yīnwèi wǒ xǐhuan báisè a!","Vì con thích màu trắng mà!"],["王一雪","Wáng Yīxuě","我觉得这条白色的不太好看，你试试那条红色的吧。","Wǒ juéde zhè tiáo báisè de bú tài hǎokàn, nǐ shìshi nà tiáo hóngsè de ba.","Mẹ thấy chiếc trắng này không đẹp lắm, con thử chiếc màu đỏ kia đi."],["刘小雪","Liú Xiǎoxuě","我没穿过红色的，红色的好看吗？","Wǒ méi chuān guo hóngsè de, hóngsè de hǎokàn ma?","Con chưa mặc màu đỏ bao giờ, màu đỏ có đẹp không?"],["王一雪","Wáng Yīxuě","就是因为没穿过，所以要试试啊！","Jiù shì yīnwèi méi chuān guo, suǒyǐ yào shìshi a!","Chính vì chưa mặc bao giờ nên mới phải thử chứ!"]]},{"t":"Bài khóa 3 · Mua cặp sách mới","l":[["刘小雪","Liú Xiǎoxuě","妈妈，我想买个新书包。","Māma, wǒ xiǎng mǎi ge xīn shūbāo.","Mẹ ơi, con muốn mua một chiếc cặp mới."],["王一雪","Wáng Yīxuě","好，那边卖书包，我们过去看看吧。","Hǎo, nàbiān mài shūbāo, wǒmen guòqù kànkan ba.","Được, bên kia bán cặp, chúng ta qua xem thử."],["刘小雪","Liú Xiǎoxuě","这么多漂亮的书包！","Zhème duō piàoliang de shūbāo!","Nhiều cặp đẹp thế!"],["王一雪","Wáng Yīxuě","红色的、绿色的、黑色的，你想买哪个？","Hóngsè de, lǜsè de, hēisè de, nǐ xiǎng mǎi nǎge?","Cặp đỏ, xanh lá, đen, con muốn mua cái nào?"],["刘小雪","Liú Xiǎoxuě","绿色的吧。","Lǜsè de ba.","Cái màu xanh lá đi."],["王一雪","Wáng Yīxuě","不错，我也觉得绿色的更好看。","Bú cuò, wǒ yě juéde lǜsè de gèng hǎokàn.","Hay đấy, mẹ cũng thấy màu xanh lá đẹp hơn."]]}],"h2-05":[{"t":"Bài khóa 1 · Chuẩn bị đến nhà bạn người Trung Quốc","l":[["安妮","Ānnī","家月，快下来吧，第一次去中国朋友家，别晚了。","Jiāyuè, kuài xiàlái ba, dì yī cì qù Zhōngguó péngyou jiā, bié wǎn le.","Gia Nguyệt, xuống nhanh đi, lần đầu đến nhà bạn người Trung Quốc, đừng đến muộn."],["白家月","Bái Jiāyuè","还有时间，你上来吧。","Hái yǒushí jiān, nǐ shànglái ba.","Vẫn còn thời gian, bạn lên đây đi."],["安妮","Ānnī","我不上去了，就在下面等你。","Wǒ bú shàngqù le, jiù zài xiàmiàn děng nǐ.","Tôi không lên đâu, đợi bạn ở dưới này."],["白家月","Bái Jiāyuè","那我一会儿就下去。","Nà wǒ yí huìr jiù xià qù.","Vậy lát nữa tôi xuống ngay."],["安妮","Ānnī","你快点儿吧。","Nǐ kuài diǎnr ba.","Bạn nhanh lên nhé."],["白家月","Bái Jiāyuè","没事，一雪姐说十一点前到就可以。","Méi shì, Yīxuě jiě shuō shí yī diǎn qián dào jiù kěyǐ.","Không sao, chị Nhất Tuyết nói trước mười một giờ đến là được."]]},{"t":"Bài khóa 2 · Gặp gia đình chị Nhất Tuyết","l":[["王一雪","Wáng Yīxuě","家月、安妮，快进来！我给你们介绍一下，这是孩子们的爷爷、奶奶。","Jiāyuè, Ānnī, kuài jìnlái! Wǒ gěi nǐmen jièshào yíxià, zhè shì háizimen de yéye, nǎinai.","Gia Nguyệt, Annie, vào nhanh đi! Chị giới thiệu một chút, đây là ông bà của bọn trẻ."],["白家月","Bái Jiāyuè","你们好！","Nǐmen hǎo!","Chúng cháu chào ông bà ạ!"],["王一雪","Wáng Yīxuě","爸，妈，这是白家月，这是安妮。她们都是一飞的学生。","Bà, mā, zhè shì Bái Jiāyuè, zhè shì Ānnī. Tāmen dōu shì Yīfēi de xuésheng.","Bố, mẹ, đây là Bạch Gia Nguyệt, đây là Annie. Hai bạn đều là học sinh của Nhất Phi."],["爷爷奶奶","Yéye nǎinai","家月、安妮，你们好！","Jiāyuè, Ānnī, nǐmen hǎo!","Gia Nguyệt, Annie, chào các cháu!"],["白家月","Bái Jiāyuè","这是送你们的礼物。","Zhè shì sòng nǐmen de lǐwù.","Đây là quà tặng mọi người."],["王一雪","Wáng Yīxuě","你们太客气了，还拿这么多礼物来！","Nǐmen tài kèqi le, hái ná zhème duō lǐwù lái!","Các em khách sáo quá, còn mang nhiều quà thế này đến!"],["白家月","Bái Jiāyuè","一雪姐，这是给孩子们准备的礼物。","Yīxuě jiě, zhè shì gěi háizimen zhǔnbèi de lǐwù.","Chị Nhất Tuyết, đây là quà em chuẩn bị cho các cháu."],["王一雪","Wáng Yīxuě","谢谢！你们别客气，快坐吧！","Xièxie! Nǐmen bié kèqi, kuài zuò ba!","Cảm ơn! Các em đừng khách sáo, ngồi nhanh đi!"]]},{"t":"Bài khóa 3 · Dùng bữa","l":[["王一雪","Wáng Yīxuě","都十二点了，我们吃饭吧。","Dōu shí èr diǎn le, wǒmen chī fàn ba.","Mười hai giờ rồi, chúng ta ăn cơm thôi."],["白家月","Bái Jiāyuè","这么多好吃的，您太客气了！","Zhème duō hǎochī de, nín tài kèqi le!","Nhiều món ngon thế này, chị khách sáo quá!"],["王一雪","Wáng Yīxuě","都是我自己做的，你们多吃点儿。","Dōu shì wǒ zìjǐ zuò de, nǐmen duō chī diǎnr.","Đều là chị tự nấu, các em ăn nhiều vào."],["白家月","Bái Jiāyuè","奶茶也很好喝，是您自己做的吗？","Nǎichá yě hěn hǎohē, shì nín zìjǐ zuò de ma?","Trà sữa cũng rất ngon, là chị tự làm ạ?"],["王一雪","Wáng Yīxuě","不是，奶茶是爷爷买的。","Bú shì, nǎichá shì yéye mǎi de.","Không phải, trà sữa là ông mua."],["白家月","Bái Jiāyuè","在哪儿买的？我还没喝过这么好喝的奶茶。","Zài nǎr mǎi de? Wǒ hái méi hē guo zhème hǎohē de nǎichá.","Mua ở đâu vậy ạ? Em chưa từng uống trà sữa nào ngon thế này."],["王一雪","Wáng Yīxuě","就在前面的商场，吃完饭你们可以跟我去看看。","Jiù zài qiánmian de shāngchǎng, chī wán fàn nǐmen kěyǐ gēn wǒ qù kànkan.","Ngay ở trung tâm thương mại phía trước, ăn xong các em có thể đi cùng chị đến xem."]]}],"h2-06":[{"t":"Bài khóa 1 · Chọn quà sinh nhật","l":[["王一雪","Wáng Yīxuě","明天就是女儿的生日了。","Míngtiān jiù shì nǚ'ér de shēngrì le.","Ngày mai là sinh nhật con gái rồi."],["刘明","Liú Míng","你不说，我还真忘了。我们给她准备个什么礼物呢？","Nǐ bù shuō, wǒ hái zhēn wàng le. Wǒmen gěi tā zhǔnbèi ge shénme lǐwù ne?","Em không nói thì anh quên mất thật. Chúng mình chuẩn bị quà gì cho con đây?"],["王一雪","Wáng Yīxuě","她喜欢画画，你觉得画笔怎么样？","Tā xǐhuan huà huà, nǐ juéde huàbǐ zěnmeyàng?","Con thích vẽ, anh thấy bút vẽ thế nào?"],["刘明","Liú Míng","就送画笔吧！那我明天上午就去买。","Jiù sòng huàbǐ ba! Nà wǒ míngtiān shàngwǔ jiù qù mǎi.","Tặng bút vẽ đi! Vậy sáng mai anh đi mua."],["王一雪","Wáng Yīxuě","好的！我再给她买个大大的生日蛋糕。","Hǎo de! Wǒ zài gěi tā mǎi ge dà dà de shēngrì dàngāo.","Được! Em sẽ mua thêm cho con một chiếc bánh sinh nhật thật to."]]},{"t":"Bài khóa 2 · Chúc mừng sinh nhật","l":[["刘明","Liú Míng","小雪，生日快乐！","Xiǎoxuě, shēngrì kuàilè!","Tiểu Tuyết, chúc mừng sinh nhật!"],["刘小明","Liú Xiǎomíng","姐姐，生日快乐！","Jiějie, shēngrì kuàilè!","Chị ơi, chúc mừng sinh nhật!"],["王一雪","Wáng Yīxuě","小雪，这是爸爸、妈妈送你的礼物。","Xiǎoxuě, zhè shì bàba, māma sòng nǐ de lǐwù.","Tiểu Tuyết, đây là quà bố mẹ tặng con."],["刘明","Liú Míng","你打开看看喜欢不喜欢。","Nǐ dǎ kāi kànkan xǐhuan bù xǐhuan.","Con mở ra xem có thích không."]]},{"t":"Bài khóa 3 · Bữa tiệc sinh nhật","l":[["刘明","Liú Míng","小雪，看看今天有什么好吃的。","Xiǎoxuě, kànkan jīntiān yǒu shénme hǎochī de.","Tiểu Tuyết, xem hôm nay có món gì ngon này."],["刘小雪","Liú Xiǎoxuě","长长的面条儿，大大的蛋糕。","Cháng cháng de miàntiáor, dà dà de dàngāo.","Mì thật dài, bánh thật to."],["刘明","Liú Míng","你看，还有鱼啊肉啊什么的，都是你喜欢吃的。","Nǐ kàn, hái yǒu yú a ròu a shénme de, dōu shì nǐ xǐhuan chī de.","Con xem, còn có cá, có thịt nữa, toàn món con thích ăn."],["刘小雪","Liú Xiǎoxuě","谢谢爸爸、妈妈！","Xièxie bàba, māma!","Cảm ơn bố mẹ!"],["王一雪","Wáng Yīxuě","快去叫弟弟过来吃饭吧，吃完饭我们还要出去玩呢。","Kuài qù jiào dìdi guò lái chī fàn ba, chī wán fàn wǒmen hái yào chū qù wán ne.","Mau gọi em lại ăn cơm đi, ăn xong chúng ta còn phải ra ngoài chơi nữa."],["刘小雪","Liú Xiǎoxuě","过生日真好啊！","Guò shēngrì zhēn hǎo a!","Được đón sinh nhật thật tuyệt!"],["王一雪","Wáng Yīxuě","是的，过生日就要吃好吃的，还要高高兴兴地玩。","Shì de, guò shēngrì jiù yào chī hǎochī de, hái yào gāo gāoxìng xìng de wán.","Đúng vậy, đón sinh nhật là phải ăn món ngon, còn phải chơi thật vui vẻ."]]}],"h2-07":[{"t":"Bài khóa 1 · Đi chơi bóng rổ","l":[["陈天中","Chén Tiānzhōng","安妮，你是什么时候从北京回来的？","Ānnī, nǐ shì shénme shíhou cóng Běijīng huílái de?","Annie, bạn từ Bắc Kinh về khi nào vậy?"],["安妮","Ānnī","昨天下午。天中，你怎么一下课就往外跑？","Zuótiān xiàwǔ. Tiānzhōng, nǐ zěnme yíxià kè jiù wǎng wài pǎo?","Chiều hôm qua. Thiên Trung, sao vừa tan học bạn đã chạy ra ngoài?"],["陈天中","Chén Tiānzhōng","我跟同学说好了，一起去打篮球。","Wǒ gēn tóngxué shuō hǎo le, yìqǐ qù dǎ lánqiú.","Tôi hẹn với bạn học rồi, cùng đi chơi bóng rổ."],["安妮","Ānnī","我也想跟你们一起玩。","Wǒ yě xiǎng gēn nǐmen yìqǐ wán.","Tôi cũng muốn chơi cùng các bạn."],["陈天中","Chén Tiānzhōng","没问题，走吧。","Méi wèntí, zǒu ba.","Không vấn đề gì, đi thôi."]]},{"t":"Bài khóa 2 · Thích môn thể thao nào?","l":[["安妮","Ānnī","天中，你是不是很喜欢打篮球？","Tiānzhōng, nǐ shì bu shì hěn xǐhuan dǎ lánqiú?","Thiên Trung, có phải bạn rất thích chơi bóng rổ không?"],["陈天中","Chén Tiānzhōng","没错。","Méi cuò.","Đúng vậy."],["安妮","Ānnī","你还喜欢什么运动？","Nǐ hái xǐhuan shénme yùndòng?","Bạn còn thích môn thể thao nào?"],["陈天中","Chén Tiānzhōng","我还喜欢踢足球，一到星期天就跟朋友们去踢球。","Wǒ hái xǐhuan tī zúqiú, yí dào xīngqītiān jiù gēn péngyou men qù tī qiú.","Tôi còn thích đá bóng, cứ đến Chủ nhật là đi đá bóng với bạn bè."],["安妮","Ānnī","你踢得怎么样？","Nǐ tī dé zěnmeyàng?","Bạn đá thế nào?"],["陈天中","Chén Tiānzhōng","我踢得还可以。","Wǒ tī dé hái kěyǐ.","Tôi đá cũng tạm được."]]},{"t":"Bài khóa 3 · Chạy bộ và bơi lội","l":[["陈天中","Chén Tiānzhōng","你篮球打得怎么样？","Nǐ lánqiú dǎ dé zěnmeyàng?","Bạn chơi bóng rổ thế nào?"],["安妮","Ānnī","打得还可以。","Dǎ dé hái kěyǐ.","Cũng tạm được."],["陈天中","Chén Tiānzhōng","跑步呢？你跑得快不快？","Pǎobù ne? Nǐ pǎo dé kuài bu kuài?","Còn chạy bộ thì sao? Bạn chạy có nhanh không?"],["安妮","Ānnī","我跑得不快，也不太喜欢跑步。","Wǒ pǎo dé bú kuài, yě bú tài xǐhuan pǎobù.","Tôi chạy không nhanh, cũng không thích chạy bộ lắm."],["陈天中","Chén Tiānzhōng","那你喜欢游泳吗？","Nà nǐ xǐhuan yóuyǒng ma?","Vậy bạn có thích bơi không?"],["安妮","Ānnī","喜欢，但我游泳游得不快。","Xǐhuan, dàn wǒ yóuyǒng yóu dé bú kuài.","Thích, nhưng tôi bơi không nhanh."]]}],"h2-08":[{"t":"Bài khóa 1 · Chọn đồng hồ","l":[["王一雪","Wáng Yīxuě","你看，这两块手表怎么样？","Nǐ kàn, zhè liǎng kuài shǒubiǎo zěnmeyàng?","Anh xem, hai chiếc đồng hồ này thế nào?"],["刘明","Liú Míng","都不错！","Dōu bú cuò!","Đều không tệ!"],["王一雪","Wáng Yīxuě","我喜欢左边这个。","Wǒ xǐhuan zuǒbian zhège.","Em thích chiếc bên trái này."],["刘明","Liú Míng","我也觉得左边的比右边的好看。","Wǒ yě juéde zuǒbian de bǐ yòubian de hǎokàn.","Anh cũng thấy chiếc bên trái đẹp hơn chiếc bên phải."],["王一雪","Wáng Yīxuě","你看看要多少钱！","Nǐ kànkan yào duōshao qián!","Anh xem giá bao nhiêu này!"],["刘明","Liú Míng","真不便宜！八千八！","Zhēn bú piányi! Bā qiān bā!","Đắt thật! Tám nghìn tám!"]]},{"t":"Bài khóa 2 · Chọn phim","l":[["刘明","Liú Míng","今天有不少电影，我们看个电影吧。","Jīntiān yǒu bù shǎo diànyǐng, wǒmen kàn ge diànyǐng ba.","Hôm nay có khá nhiều phim, chúng ta xem phim đi."],["王一雪","Wáng Yīxuě","好啊！我们看哪个？","Hǎo a! Wǒmen kàn nǎge?","Hay đấy! Chúng ta xem phim nào?"],["刘明","Liú Míng","我记得你喜欢看爱情片，我们看那个爱情片，怎么样？","Wǒ jìde nǐ xǐhuan kàn àiqíngpiàn, wǒmen kàn nàge àiqíngpiàn, zěnmeyàng?","Anh nhớ em thích xem phim tình cảm, mình xem phim tình cảm kia nhé?"],["王一雪","Wáng Yīxuě","还是看这个吧，我看网上说这个电影比那个爱情片更有意思。","Háishi kàn zhège ba, wǒ kàn wǎngshàng shuō zhège diànyǐng bǐ nàge àiqíngpiàn gèng yǒu yìsi.","Hay là xem phim này đi, em thấy trên mạng nói phim này thú vị hơn phim tình cảm kia."],["刘明","Liú Míng","好。我去买票。","Hǎo. Wǒ qù mǎipiào.","Được. Anh đi mua vé."],["王一雪","Wáng Yīxuě","到网上买吧，网上买比在这里买便宜。","Dào wǎngshàng mǎi ba, wǎngshàng mǎi bǐ zài zhèlǐ mǎi piányi.","Mua trên mạng đi, mua trên mạng rẻ hơn mua ở đây."]]},{"t":"Bài khóa 3 · Sinh nhật bất ngờ","l":[["刘明","Liú Míng","您好！就要这几个菜吧，谢谢！","Nín hǎo! Jiù yào zhè jǐ ge cài ba, xièxie!","Chào chị! Cho chúng tôi mấy món này thôi, cảm ơn!"],["王一雪","Wáng Yīxuě","怎么点这么多菜？","Zěnme diǎn zhème duō cài?","Sao gọi nhiều món thế?"],["刘明","Liú Míng","你想想，今天是几月几号？","Nǐ xiǎngxiang, jīntiān shì jǐ yuè jǐ hào?","Em nghĩ xem, hôm nay là ngày bao nhiêu tháng mấy?"],["王一雪","Wáng Yīxuě","八月二十七号。啊！我的生日！","Bā yuè èr shí qī hào. A! Wǒ de shēngrì!","Ngày 27 tháng 8. A! Sinh nhật của em!"],["刘明","Liú Míng","生日快乐！虽然你忘了，但是我记得。看看这是什么？","Shēngrì kuàilè! Suīrán nǐ wàng le, dànshì wǒ jìde. Kànkan zhè shì shénme?","Chúc mừng sinh nhật! Tuy em quên, nhưng anh nhớ. Xem đây là gì nào?"],["王一雪","Wáng Yīxuě","手表！吃饭、看电影、买手表，今天花了不少钱吧？","Shǒubiǎo! Chī fàn, kàn diànyǐng, mǎi shǒubiǎo, jīntiān huā le bù shǎo qián ba?","Đồng hồ! Ăn cơm, xem phim, mua đồng hồ, hôm nay tốn không ít tiền nhỉ?"],["刘明","Liú Míng","虽然花了一些钱，但是我们过了一个快乐的生日。","Suīrán huā le yìxiē qián, dànshì wǒmen guò le yí ge kuàilè de shēngrì.","Tuy tốn một ít tiền, nhưng chúng ta đã có một ngày sinh nhật vui vẻ."]]}],"h2-09":[{"t":"Bài khóa 1 · Mua quần cho con trai","l":[["王一雪","Wáng Yīxuě","儿子的裤子坏了，我们给他买条新的吧。","Érzi de kùzi huài le, wǒmen gěi tā mǎi tiáo xīn de ba.","Quần của con trai rách rồi, chúng mình mua cho nó chiếc mới nhé."],["刘明","Liú Míng","好啊。","Hǎo a.","Được thôi."],["王一雪","Wáng Yīxuě","你看这条黑色的怎么样？","Nǐ kàn zhè tiáo hēisè de zěnmeyàng?","Anh xem chiếc màu đen này thế nào?"],["刘明","Liú Míng","没有你上次买的那条好看。","Méiyǒu nǐ shàng cì mǎi de nà tiáo hǎokàn.","Không đẹp bằng chiếc em mua lần trước."],["王一雪","Wáng Yīxuě","旁边那个男孩儿就穿了这样的裤子，我觉得很好看啊！","Pángbiān nàge nánháir jiù chuān le zhèyàng de kùzi, wǒ juéde hěn hǎokàn a!","Cậu bé bên cạnh mặc đúng kiểu quần này, em thấy đẹp mà!"],["刘明","Liú Míng","儿子的个子没有他那么高，穿上就不会太好看。","Érzi de gèzi méiyǒu tā nàme gāo, chuān shàng jiù bú huì tài hǎokàn.","Con trai không cao bằng cậu bé đó, mặc vào sẽ không đẹp lắm."],["王一雪","Wáng Yīxuě","好吧，我们再去那边看看。","Hǎo ba, wǒmen zài qù nàbiān kànkan.","Được rồi, chúng mình sang bên kia xem thêm."]]},{"t":"Bài khóa 2 · Uống trà sữa hay cà phê","l":[["王一雪","Wáng Yīxuě","门口有家奶茶店。你想喝杯奶茶吗？","Ménkǒu yǒu jiā nǎichá diàn. Nǐ xiǎng hē bēi nǎichá ma?","Ở cổng có một quán trà sữa. Anh có muốn uống một ly trà sữa không?"],["刘明","Liú Míng","我想喝咖啡，还是去咖啡店吧。","Wǒ xiǎng hē kāfēi, háishi qù kāfēi diàn ba.","Anh muốn uống cà phê, hay là đến quán cà phê đi."],["王一雪","Wáng Yīxuě","咖啡店离这儿有点儿远。","Kāfēi diàn lí zhèr yǒudiǎnr yuǎn.","Quán cà phê cách đây hơi xa."],["刘明","Liú Míng","没关系，那家店的咖啡很好喝。","Méi guānxi, nà jiā diàn de kāfēi hěn hǎohē.","Không sao, cà phê quán đó rất ngon."],["王一雪","Wáng Yīxuě","那你等一下，我去买杯奶茶。","Nà nǐ děng yíxià, wǒ qù mǎi bēi nǎichá.","Vậy anh đợi một chút, em đi mua ly trà sữa."],["刘明","Liú Míng","你不想喝咖啡吗？","Nǐ bù xiǎng hē kāfēi ma?","Em không muốn uống cà phê à?"],["王一雪","Wáng Yīxuě","喝了咖啡，晚上就别想睡觉了。","Hē le kāfēi, wǎnshang jiù bié xiǎng shuìjiào le.","Uống cà phê rồi, tối đừng mong ngủ được."]]},{"t":"Bài khóa 3 · Về nhà","l":[["刘明","Liú Míng","我们打车回去吧。","Wǒmen dǎchē huíqù ba.","Chúng mình đi taxi về nhé."],["王一雪","Wáng Yīxuě","这里离家很近，还是走路吧。","Zhèlǐ lí jiā hěn jìn, háishi zǒulù ba.","Chỗ này cách nhà rất gần, vẫn nên đi bộ."],["刘明","Liú Míng","要走多长时间？","Yào zǒu duō zhǎng shíjiān?","Đi bộ mất bao lâu?"],["王一雪","Wáng Yīxuě","走半个多小时就到了。","Zǒu bàn ge duō xiǎoshí jiù dào le.","Đi hơn nửa tiếng là đến."],["刘明","Liú Míng","好的。每天上下班都坐车，今天运动运动吧。","Hǎo de. Měi tiān shàng xiàbān dōu zuò chē, jīntiān yùndòng yùndòng ba.","Được rồi. Ngày nào đi làm cũng đi xe, hôm nay vận động một chút."]]}],"h2-10":[{"t":"Bài khóa 1 · Chuẩn bị khai giảng","l":[["刘明","Liú Míng","小明，你们明天开学，你准备好了吗？","Xiǎomíng, nǐmen míngtiān kāixué, nǐ zhǔnbèi hǎo le ma?","Tiểu Minh, ngày mai các con khai giảng, con chuẩn bị xong chưa?"],["刘小明","Liú Xiǎomíng","明天就开学吗？爸爸，我的书包你看见了吗？","Míngtiān jiù kāixué ma? Bàba, wǒ de shūbāo nǐ kànjiàn le ma?","Ngày mai đã khai giảng rồi ạ? Bố ơi, bố có thấy cặp của con không?"],["刘明","Liú Míng","书包在门后面。","Shūbāo zài mén hòumian.","Cặp ở sau cánh cửa."],["刘小明","Liú Xiǎomíng","书在哪儿呢？笔呢？","Shū zài nǎr ne? Bǐ ne?","Sách đâu rồi ạ? Còn bút đâu?"],["刘明","Liú Míng","书在床上，笔在桌子上。","Shū zài chuáng shàng, bǐ zài zhuōzi shàng.","Sách ở trên giường, bút ở trên bàn."],["刘小明","Liú Xiǎomíng","太好了！现在都准备好了。","Tài hǎo le! Xiànzài dōu zhǔnbèi hǎo le.","Tuyệt quá! Bây giờ đã chuẩn bị xong hết rồi."],["刘明","Liú Míng","这次爸爸帮你，下次你自己准备，好不好？","Zhè cì bàba bāng nǐ, xià cì nǐ zìjǐ zhǔnbèi, hǎo bu hǎo?","Lần này bố giúp con, lần sau con tự chuẩn bị, được không?"],["刘小明","Liú Xiǎomíng","好！","Hǎo!","Vâng!"]]},{"t":"Bài khóa 2 · Ôn thi","l":[["王一雪","Wáng Yīxuě","小雪，你在做什么呢？","Xiǎoxuě, nǐ zài zuò shénme ne?","Tiểu Tuyết, con đang làm gì đấy?"],["刘小雪","Liú Xiǎoxuě","明天考试，我在看书呢。","Míngtiān kǎoshì, wǒ zài kàn shū ne.","Mai thi, con đang đọc sách ạ."],["王一雪","Wáng Yīxuě","这些词要好好看看。","Zhèxiē cí yào hǎo hǎokàn kàn.","Những từ này phải xem kỹ."],["刘小雪","Liú Xiǎoxuě","我看过了，意思也都懂了。","Wǒ kàn guo le, yìsi yě dōu dǒng le.","Con xem rồi, nghĩa cũng hiểu hết rồi."],["王一雪","Wáng Yīxuě","你的本子呢？本子上做错的题也要看一看。","Nǐ de běnzi ne? Běnzi shàng zuò cuò de tí yě yào kàn yí kàn.","Vở của con đâu? Những bài làm sai trong vở cũng phải xem lại."],["刘小雪","Liú Xiǎoxuě","妈妈，是您准备考试还是我准备考试？","Māma, shì nín zhǔnbèi kǎoshì háishi wǒ zhǔnbèi kǎoshì?","Mẹ ơi, là mẹ ôn thi hay con ôn thi vậy ạ?"]]},{"t":"Bài khóa 3 · Thi xong","l":[["刘小雪","Liú Xiǎoxuě","妈妈，我回来了！","Māma, wǒ huílái le!","Mẹ ơi, con về rồi!"],["王一雪","Wáng Yīxuě","我买了奶茶，就在桌子上，自己去拿吧。","Wǒ mǎi le nǎichá, jiù zài zhuōzi shàng, zìjǐ qù ná ba.","Mẹ mua trà sữa rồi, ở trên bàn đấy, con tự lấy nhé."],["刘小雪","Liú Xiǎoxuě","谢谢妈妈！","Xièxie māma!","Con cảm ơn mẹ!"],["王一雪","Wáng Yīxuě","今天考试考得怎么样？","Jīntiān kǎoshì kǎo dé zěnmeyàng?","Hôm nay con thi thế nào?"],["刘小雪","Liú Xiǎoxuě","我觉得比上次好。","Wǒ juéde bǐ shàng cì hǎo.","Con thấy tốt hơn lần trước."],["王一雪","Wáng Yīxuě","真不错！饭菜快要做好了，你叫弟弟一起去洗手吧。","Zhēn bú cuò! Fàn cài kuàiyào zuò hǎo le, nǐ jiào dìdi yìqǐ qù xǐ shǒu ba.","Giỏi lắm! Cơm sắp nấu xong rồi, con gọi em cùng đi rửa tay đi."],["刘小明","Liú Xiǎomíng","妈妈，我是第一名，姐姐还没洗完呢。","Māma, wǒ shì dì yī míng, jiějie hái méi xǐ wán ne.","Mẹ ơi, con là nhất, chị vẫn chưa rửa xong ạ."],["王一雪","Wáng Yīxuě","你洗得真快啊！","Nǐ xǐ dé zhēn kuài a!","Con rửa nhanh thật đấy!"]]}],"h2-11":[{"t":"Bài khóa 1 · Đau đầu","l":[["王一飞","Wáng Yīfēi","家月，都下课了，你怎么还不回家？","Jiāyuè, dōu xià kè le, nǐ zěnme hái bù huí jiā?","Gia Nguyệt, tan học rồi, sao em vẫn chưa về nhà?"],["白家月","Bái Jiāyuè","我头疼，不太舒服。","Wǒ tóu téng, bú tài shūfu.","Em đau đầu, không khỏe lắm."],["王一飞","Wáng Yīfēi","你这几天经常头疼，去医院看看吧。","Nǐ zhè jǐ tiān jīngcháng tóu téng, qù yīyuàn kànkan ba.","Mấy hôm nay em hay đau đầu, đến bệnh viện khám đi."],["白家月","Bái Jiāyuè","我想休息一下，现在不能动，一动就疼。","Wǒ xiǎng xiūxi yíxià, xiànzài bù néng dòng, yí dòng jiù téng.","Em muốn nghỉ một chút, bây giờ không cử động được, cứ động là đau."],["王一飞","Wáng Yīfēi","那你在这儿坐着，我去开车，一会儿送你去医院。","Nà nǐ zài zhèr zuò zhe, wǒ qù kāichē, yí huìr sòng nǐ qù yīyuàn.","Vậy em ngồi đây, thầy đi lấy xe, lát nữa đưa em đến bệnh viện."],["白家月","Bái Jiāyuè","谢谢王老师。","Xièxie Wáng lǎoshī.","Em cảm ơn thầy Vương."]]},{"t":"Bài khóa 2 · Trên đường đến bệnh viện","l":[["王一飞","Wáng Yīfēi","现在路上车多，还下着雪，我开慢一点儿。","Xiànzài lùshang chē duō, hái xià zhe xuě, wǒ kāi màn yì diǎnr.","Bây giờ trên đường nhiều xe, lại còn đang có tuyết, thầy lái chậm một chút."],["白家月","Bái Jiāyuè","没问题，现在头没那么疼了。","Méi wèntí, xiànzài tóu méi nàme téng le.","Không sao ạ, bây giờ đầu không đau đến thế nữa."],["王一飞","Wáng Yīfēi","好。李文来电话了，你帮我接一下。","Hǎo. Lǐ Wén lái diànhuà le, nǐ bāng wǒ jiē yíxià.","Được. Lý Văn gọi điện đến, em nghe giúp thầy một chút."],["白家月","Bái Jiāyuè","喂，李文，王老师开着车呢，你找她有事吗？","Wèi, Lǐ Wén, Wáng lǎoshī kāi zhe chē ne, nǐ zhǎo tā yǒu shì ma?","A lô, Lý Văn, thầy Vương đang lái xe, bạn tìm thầy có việc gì không?"],["李文","Lǐ Wén","没什么事。今天雪这么大，你们开车去哪儿啊？","Méi shénme shì. Jīntiān xuě zhème dà, nǐmen kāichē qù nǎr a?","Không có việc gì. Hôm nay tuyết rơi to thế, các bạn lái xe đi đâu vậy?"],["白家月","Bái Jiāyuè","去医院，我头有点儿疼。","Qù yīyuàn, wǒ tóu yǒudiǎnr téng.","Đến bệnh viện, tôi hơi đau đầu."],["李文","Lǐ Wén","那我一会儿去看看你。","Nà wǒ yí huìr qù kànkan nǐ.","Vậy lát nữa tôi đến thăm bạn."]]},{"t":"Bài khóa 3 · Thăm bệnh","l":[["白家月","Bái Jiāyuè","李文，快请进！","Lǐ Wén, kuài qǐng jìn!","Lý Văn, mời vào nhanh!"],["李文","Lǐ Wén","家月，你怎么样了？头还疼吗？","Jiāyuè, nǐ zěnmeyàng le? Tóu hái téng ma?","Gia Nguyệt, bạn thế nào rồi? Đầu còn đau không?"],["白家月","Bái Jiāyuè","不那么疼了。医生开了一些药，吃完就好多了。","Bú nàme téng le. Yīshēng kāi le yìxiē yào, chī wán jiù hǎo duō le.","Không đau đến thế nữa. Bác sĩ kê một ít thuốc, uống xong đã đỡ nhiều."],["李文","Lǐ Wén","那就好！","Nà jiù hǎo!","Thế thì tốt!"],["王一飞","Wáng Yīfēi","家月，你想不想吃点儿东西？","Jiāyuè, nǐ xiǎng bu xiǎng chī diǎnr dōngxi?","Gia Nguyệt, em có muốn ăn chút gì không?"],["李文","Lǐ Wén","吃点儿吧，身体不舒服时更要好好吃饭。","Chī diǎnr ba, shēntǐ bù shūfu shí gèng yào hǎo hǎochī fàn.","Ăn một chút đi, lúc cơ thể không khỏe càng phải ăn uống đàng hoàng."],["白家月","Bái Jiāyuè","吃点儿什么呢？","Chī diǎnr shénme ne?","Ăn gì bây giờ nhỉ?"],["王一飞","Wáng Yīfēi","你最喜欢吃中国菜，我做几个中国菜吧。","Nǐ zuì xǐhuan chī Zhōngguó cài, wǒ zuò jǐ ge Zhōngguó cài ba.","Em thích ăn món Trung Quốc nhất, để thầy nấu vài món nhé."],["白家月","Bái Jiāyuè","好的，谢谢王老师。","Hǎo de, xièxie Wáng lǎoshī.","Vâng, em cảm ơn thầy Vương."]]}],"h2-12":[{"t":"Bài khóa 1 · Gọi điện trò chuyện","l":[["王一雪","Wáng Yīxuě","喂，家月，是你呀！有什么事情吗？","Wèi, Jiāyuè, shì nǐ ya! Yǒu shénme shìqing ma?","A lô, Gia Nguyệt, là em à! Có việc gì không?"],["白家月","Bái Jiāyuè","没什么事，就想跟您说说话。","Méi shénme shì, jiù xiǎng gēn nín shuōshuo huà.","Không có việc gì ạ, chỉ muốn trò chuyện với chị."],["王一雪","Wáng Yīxuě","好啊。你今天没课吗？","Hǎo a. Nǐ jīntiān méi kè ma?","Được thôi. Hôm nay em không có tiết à?"],["白家月","Bái Jiāyuè","下午有课。您那里天气怎么样？","Xiàwǔ yǒu kè. Nín nàlǐ tiānqì zěnmeyàng?","Chiều em có tiết. Chỗ chị thời tiết thế nào?"],["王一雪","Wáng Yīxuě","北京这几天虽然是晴天，但是有点儿冷。","Běijīng zhè jǐ tiān suīrán shì qíng tiān, dànshì yǒudiǎnr lěng.","Mấy ngày nay Bắc Kinh tuy trời nắng nhưng hơi lạnh."],["白家月","Bái Jiāyuè","我这里比北京冷多了，外边还正下着雪呢！","Wǒ zhèlǐ bǐ Běijīng lěng duō le, wàibian hái zhèng xià zhe xuě ne!","Chỗ em lạnh hơn Bắc Kinh nhiều, bên ngoài còn đang có tuyết rơi!"]]},{"t":"Bài khóa 2 · Chị em gọi điện","l":[["王一雪","Wáng Yīxuě","喂，一飞，听家月说你那边下雪了，下得大不大？","Wèi, Yīfēi, tīng Jiāyuè shuō nǐ nàbiān xiàxuě le, xià dé dà bu dà?","A lô, Nhất Phi, nghe Gia Nguyệt nói chỗ em có tuyết rơi, có to không?"],["王一飞","Wáng Yīfēi","今天不大，昨天比今天下得大。","Jīntiān bú dà, zuótiān bǐ jīntiān xià dé dà.","Hôm nay không to, hôm qua rơi to hơn hôm nay."],["王一雪","Wáng Yīxuě","天气不好，你去外面的时候多穿点儿衣服。","Tiānqì bù hǎo, nǐ qù wàimian de shíhou duō chuān diǎnr yīfu.","Thời tiết xấu, lúc ra ngoài em mặc thêm quần áo."],["王一飞","Wáng Yīfēi","这几天我在网上上课，没出去过。","Zhè jǐ tiān wǒ zài wǎngshàng shàngkè, méi chū qù guo.","Mấy hôm nay em dạy trực tuyến, chưa ra ngoài."],["王一雪","Wáng Yīxuě","那就好，有事记得给我打电话。","Nà jiù hǎo, yǒu shì jìde gěi wǒ dǎ diànhuà.","Thế thì tốt, có việc nhớ gọi điện cho chị."],["王一飞","Wáng Yīfēi","好的。现在不下雪了，我出去买点儿吃的。","Hǎo de. Xiànzài bú xiàxuě le, wǒ chū qù mǎi diǎnr chī de.","Vâng. Bây giờ tuyết ngừng rồi, em ra ngoài mua chút đồ ăn."],["王一雪","Wáng Yīxuě","一次多买点儿，阴天下雪什么的就少出去吧。","Yī cì duō mǎi diǎnr, yīn tiān xiàxuě shénme de jiù shǎo chū qù ba.","Mua nhiều một lần, những hôm trời âm u có tuyết thì ít ra ngoài thôi."]]},{"t":"Bài khóa 3 · Rủ đi chạy bộ","l":[["李文","Lǐ Wén","喂，家月，今天天气不错，我们去跑步吧！","Wèi, Jiāyuè, jīntiān tiānqì bú cuò, wǒmen qù pǎobù ba!","A lô, Gia Nguyệt, hôm nay thời tiết đẹp, chúng ta đi chạy bộ đi!"],["白家月","Bái Jiāyuè","你跑步跑得比我快，我们能一起跑吗？","Nǐ pǎobù pǎo dé bǐ wǒ kuài, wǒmen néng yìqǐ pǎo ma?","Bạn chạy nhanh hơn tôi, chúng ta chạy cùng nhau được không?"],["李文","Lǐ Wén","可以的，我慢慢跑，等着你。","Kěyǐ de, wǒ màn màn pǎo, děng zhe nǐ.","Được chứ, tôi chạy chậm thôi, đợi bạn."],["白家月","Bái Jiāyuè","好吧。你真爱跑步啊！","Hǎo ba. Nǐ zhēn ài pǎobù a!","Được rồi. Bạn thích chạy bộ thật đấy!"],["李文","Lǐ Wén","我从小就经常跟爸爸跑步，跑步能让人快乐！","Wǒ cóngxiǎo jiù jīngcháng gēn bàba pǎobù, pǎobù néng ràng rén kuàilè!","Từ nhỏ tôi đã thường chạy bộ cùng bố, chạy bộ khiến người ta vui vẻ!"],["白家月","Bái Jiāyuè","好，那我准备一下。","Hǎo, nà wǒ zhǔnbèi yíxià.","Được, vậy tôi chuẩn bị một chút."],["李文","Lǐ Wén","我现在坐地铁去找你，一会儿楼下见。","Wǒ xiànzài zuò dìtiě qù zhǎo nǐ, yí huìr lóu xià jiàn.","Bây giờ tôi đi tàu điện ngầm đến tìm bạn, lát nữa gặp nhau dưới lầu."]]}],"h2-13":[{"t":"Bài khóa 1 · Chuẩn bị quà năm mới cho cô giáo","l":[["白家月","Bái Jiāyuè","时间过得真快啊！新年就要到了。","Shíjiān guò dé zhēn kuài a! Xīnnián jiù yào dào le.","Thời gian trôi nhanh thật! Năm mới sắp đến rồi."],["陈天中","Chén Tiānzhōng","这一年王老师教我们中文，每天工作都很累。","Zhè yì nián Wáng lǎoshī jiào wǒmen Zhōngwén, měi tiān gōngzuò dōu hěn lèi.","Cả năm nay cô Vương dạy chúng ta tiếng Trung, mỗi ngày làm việc đều rất mệt."],["白家月","Bái Jiāyuè","是啊，她教得很好。因为她，我们都非常爱上中文课了。","Shì a, tā jiào dé hěn hǎo. Yīnwèi tā, wǒmen dōu fēicháng ài shàng Zhōngwén kè le.","Đúng vậy, cô dạy rất hay. Nhờ cô, chúng ta đều rất yêu thích giờ tiếng Trung."],["陈天中","Chén Tiānzhōng","我们给她准备个新年礼物吧。你觉得送给她什么好呢？","Wǒmen gěi tā zhǔnbèi ge xīnnián lǐwù ba. Nǐ juéde sòng gěi tā shénme hǎo ne?","Chúng ta chuẩn bị cho cô một món quà năm mới nhé. Bạn thấy tặng cô gì thì tốt?"],["白家月","Bái Jiāyuè","王老师喜欢花，就送给她花吧。","Wáng lǎoshī xǐhuan huā, jiù sòng gěi tā huā ba.","Cô Vương thích hoa, vậy tặng cô hoa đi."],["陈天中","Chén Tiānzhōng","那我们去花店看看，现在买花的人多，希望花店还有漂亮的花。","Nà wǒmen qù huā diàn kànkan, xiànzài mǎi huā de rén duō, xīwàng huā diàn hái yǒu piàoliang de huā.","Vậy chúng ta đến tiệm hoa xem, bây giờ người mua hoa nhiều, hy vọng tiệm vẫn còn hoa đẹp."]]},{"t":"Bài khóa 2 · Trong giờ học","l":[["白家月","Bái Jiāyuè","王老师，今天的词比昨天多了十个。","Wáng lǎoshī, jīntiān de cí bǐ zuótiān duō le shí ge.","Thầy Vương, từ hôm nay nhiều hơn hôm qua mười từ ạ."],["王一飞","Wáng Yīfēi","是啊！你们都学会了吗？","Shì a! Nǐmen dōu xué huì le ma?","Đúng vậy! Các em đều học thuộc rồi chứ?"],["安妮","Ānnī","学会了，没有问题。","Xué huì le, méiyǒu wèntí.","Học xong rồi ạ, không có vấn đề gì."],["王一飞","Wáng Yīfēi","好。现在我来说，你们在本子上面写。","Hǎo. Xiànzài wǒ lái shuō, nǐmen zài běnzi shàngmian xiě.","Tốt. Bây giờ thầy đọc, các em viết vào vở."],["王一飞","Wáng Yīfēi","同学们，“洗手间”的“间”字写错了，它的里面是“日”，不是“口”。","Tóngxuémen, “Xǐshǒujiān” de“Jiān” zì xiě cuò le, tā de lǐmian shì“Rì”, bú shì“Kǒu”.","Các em, chữ “间” trong “洗手间” viết sai rồi, bên trong là “日”, không phải “口”."],["白家月","Bái Jiāyuè","“日”比“口”多一笔，写“口”就是“问题”的“问”了。","“Rì” bǐ“Kǒu” duō yì bǐ, xiě“Kǒu” jiù shì“Wèntí” de“Wèn” le.","“日” nhiều hơn “口” một nét, viết “口” thì thành chữ “问” trong “问题” rồi."],["王一飞","Wáng Yīfēi","没错，你说得很对。","Méi cuò, nǐ shuō dé hěn duì.","Đúng thế, em nói rất đúng."]]},{"t":"Bài khóa 3 · Mua vở","l":[["安妮","Ānnī","家月，你觉得这个本子怎么样？","Jiāyuè, nǐ juéde zhège běnzi zěnmeyàng?","Gia Nguyệt, bạn thấy quyển vở này thế nào?"],["白家月","Bái Jiāyuè","很漂亮，多少钱一个？","Hěn piàoliang, duōshao qián yí ge?","Rất đẹp, bao nhiêu tiền một quyển?"],["安妮","Ānnī","比我们一起买的那个本子贵一点儿。","Bǐ wǒmen yìqǐ mǎi de nàge běnzi guì yì diǎnr.","Đắt hơn quyển chúng ta cùng mua một chút."],["白家月","Bái Jiāyuè","这么漂亮的本子，不可能贵一点儿吧？","Zhème piàoliang de běnzi, bù kěnéng guì yì diǎnr ba?","Quyển vở đẹp thế này, không thể chỉ đắt hơn một chút đâu nhỉ?"],["安妮","Ānnī","我是上网买的，真没那么贵。我买了两个，送你一个。","Wǒ shì shàngwǎng mǎi de, zhēn méi nàme guì. Wǒ mǎi le liǎng ge, sòng nǐ yí ge.","Tôi mua trên mạng, thật sự không đắt đến thế. Tôi mua hai quyển, tặng bạn một quyển."],["白家月","Bái Jiāyuè","谢谢！那我送给你什么呢？","Xièxie! Nà wǒ sòng gěi nǐ shénme ne?","Cảm ơn! Vậy tôi tặng bạn gì đây?"],["安妮","Ānnī","咖啡杯吧，我最喜欢喝咖啡了。","Kāfēi bēi ba, wǒ zuì xǐhuan hē kāfēi le.","Tặng cốc cà phê đi, tôi thích uống cà phê nhất."],["白家月","Bái Jiāyuè","好，那样我们就都有新年礼物了！","Hǎo, nàyàng wǒmen jiù dōu yǒu xīnnián lǐwù le!","Được, như vậy chúng ta đều có quà năm mới rồi!"]]}],"h2-14":[{"t":"Bài khóa 1 · Người lạ dưới lầu","l":[["李文","Lǐ Wén","王老师，你家楼下站着一个人。","Wáng lǎoshī, nǐ jiā lóu xià zhàn zhe yí ge rén.","Thầy Vương, dưới lầu nhà thầy có một người đang đứng."],["王一飞","Wáng Yīfēi","我家楼下？我看看。","Wǒ jiā lóu xià? Wǒ kànkan.","Dưới lầu nhà tôi? Để tôi xem."],["李文","Lǐ Wén","那个人穿着黑色的裤子，手里还拿着一个黑色的包。","Nàge rén chuān zhe hēisè de kùzi, shǒu lǐ hái ná zhe yí ge hēisè de bāo.","Người đó mặc quần đen, tay còn cầm một chiếc túi đen."],["王一飞","Wáng Yīfēi","我看见那个人了，他是我男朋友。","Wǒ kànjiàn nàge rén le, tā shì wǒ nánpéngyou.","Tôi thấy người đó rồi, anh ấy là bạn trai của tôi."],["李文","Lǐ Wén","那我们快过去吧。","Nà wǒmen kuài guòqù ba.","Vậy chúng ta mau xuống đó đi."]]},{"t":"Bài khóa 2 · Gặp lại bạn trai","l":[["王一飞","Wáng Yīfēi","同乐，真是你呀！上次打电话，你说有时间过来看我，没想到这么快就来了！","Tónglè, zhēn shì nǐ ya! Shàng cì dǎ diànhuà, nǐ shuō yǒushí jiān guò lái kàn wǒ, méi xiǎng dào zhème kuài jiù lái le!","Đồng Nhạc, đúng là anh rồi! Lần trước gọi điện anh nói có thời gian sẽ sang thăm em, không ngờ anh đến nhanh thế!"],["杨同乐","Yáng Tónglè","就要过年了，你一个人在这儿多没意思啊，所以我就早过来了。","Jiù yào guònián le, nǐ yí ge rén zài zhèr duō méi yìsi a, suǒyǐ wǒ jiù zǎo guò lái le.","Sắp đến Tết rồi, em ở đây một mình chán lắm, nên anh sang sớm."],["王一飞","Wáng Yīfēi","你能来，我太高兴了！","Nǐ néng lái, wǒ tài gāoxìng le!","Anh đến được, em vui quá!"],["杨同乐","Yáng Tónglè","一飞，你旁边这位是？","Yīfēi, nǐ pángbiān zhè wèi shì?","Nhất Phi, vị bên cạnh em là ai vậy?"],["王一飞","Wáng Yīfēi","同乐，这是李文，他在我们学校学医。李文，这是我男朋友杨同乐。","Tónglè, zhè shì Lǐ Wén, tā zài wǒmen xuéxiào xué yī. Lǐ Wén, zhè shì wǒ nánpéngyou Yáng Tónglè.","Đồng Nhạc, đây là Lý Văn, cậu ấy học y ở trường chúng em. Lý Văn, đây là bạn trai tôi, Dương Đồng Nhạc."],["杨同乐","Yáng Tónglè","李文，很高兴认识你！","Lǐ Wén, hěn gāoxìng rènshi nǐ!","Lý Văn, rất vui được làm quen với bạn!"],["李文","Lǐ Wén","认识你我也很高兴！我家就在前面那个楼，有时间回来玩。","Rènshi nǐ wǒ yě hěn gāoxìng! Wǒ jiā jiù zài qiánmian nàge lóu, yǒushí jiān huílái wán.","Quen anh tôi cũng rất vui! Nhà tôi ở ngay tòa nhà phía trước, có thời gian anh ghé chơi nhé."]]},{"t":"Bài khóa 3 · Người hàng xóm","l":[["杨同乐","Yáng Tónglè","一飞，你住的房子真不错，很大，离学校也不远。","Yīfēi, nǐ zhù de fángzi zhēn bú cuò, hěn dà, lí xuéxiào yě bù yuǎn.","Nhất Phi, nhà em ở đẹp thật, rộng, cách trường cũng không xa."],["王一飞","Wáng Yīfēi","是啊！我楼下还住着一家中国人，他们人很好。","Shì a! Wǒ lóu xià hái zhù zhe yì jiā Zhōngguórén, tāmen rén hěn hǎo.","Đúng vậy! Dưới lầu em còn có một gia đình người Trung Quốc ở, họ rất tốt."],["杨同乐","Yáng Tónglè","这样你有事情就可以找他们帮忙。","Zhèyàng nǐ yǒu shìqing jiù kěyǐ zhǎo tāmen bāngmáng.","Như vậy em có việc là có thể nhờ họ giúp."],["王一飞","Wáng Yīfēi","对，我也帮他们家的小孩儿学中文。","Duì, wǒ yě bāng tāmen jiā de xiǎoháir xué Zhōngwén.","Vâng, em cũng giúp bọn trẻ nhà họ học tiếng Trung."],["杨同乐","Yáng Tónglè","我记得你跟我说过，是个女孩儿，学得也很好。","Wǒ jìde nǐ gēn wǒ shuō guo, shì ge nǚháir, xué dé yě hěn hǎo.","Anh nhớ em từng nói, là một bé gái, học cũng rất giỏi."],["王一飞","Wáng Yīfēi","没错，她经常跑上来找我玩。","Méi cuò, tā jīngcháng pǎo shànglái zhǎo wǒ wán.","Đúng vậy, bé thường chạy lên tìm em chơi."],["杨同乐","Yáng Tónglè","你问问他们什么时候有时间，我请他们吃午饭。","Nǐ wènwen tāmen shénme shíhou yǒushí jiān, wǒ qǐng tāmen chī wǔfàn.","Em hỏi họ khi nào rảnh, anh mời họ ăn trưa."]]}],"h2-15":[{"t":"Bài khóa 1 · Giờ thi","l":[["王一飞","Wáng Yīfēi","考试就要开始了，请大家先写上姓名，写好后就可以做题了。","Kǎoshì jiù yào kāishǐ le, qǐng dàjiā xiān xiě shàng xìngmíng, xiě hǎo hòu jiù kěyǐ zuò tí le.","Bài thi sắp bắt đầu, mời mọi người ghi họ tên trước, ghi xong là có thể làm bài."],["白家月","Bái Jiāyuè","老师，我做完了。","Lǎoshī, wǒ zuòwán le.","Thưa thầy, em làm xong rồi ạ."],["陈天中","Chén Tiānzhōng","老师，我也做完了。","Lǎoshī, wǒ yě zuòwán le.","Thưa thầy, em cũng làm xong rồi ạ."],["王一飞","Wáng Yīfēi","对了，你们考完试想做什么？","Duì le, nǐmen kǎowán shì xiǎng zuò shénme?","À này, thi xong các em muốn làm gì?"],["白家月","Bái Jiāyuè","我很想去中国，虽然去过一次，但是很想再去一次。","Wǒ hěn xiǎng qù Zhōngguó, suīrán qù guo yí cì, dànshì hěn xiǎng zài qù yí cì.","Em rất muốn đến Trung Quốc, tuy đã đi một lần nhưng rất muốn đi thêm lần nữa."],["王一飞","Wáng Yīfēi","不错，到中国后你就可以经常说中文了。","Bú cuò, dào Zhōngguó hòu nǐ jiù kěyǐ jīngcháng shuō Zhōngwén le.","Hay đấy, đến Trung Quốc rồi em có thể thường xuyên nói tiếng Trung."]]},{"t":"Bài khóa 2 · Kế hoạch đi Bắc Kinh","l":[["白家月","Bái Jiāyuè","考试完了，我现在可以出国旅游了。","Kǎoshì wán le, wǒ xiànzài kěyǐ chūguó lǚyóu le.","Thi xong rồi, giờ tôi có thể ra nước ngoài du lịch."],["李文","Lǐ Wén","你要去哪儿？","Nǐ yào qù nǎr?","Bạn định đi đâu?"],["白家月","Bái Jiāyuè","我要再去一次北京。","Wǒ yào zài qù yí cì Běijīng.","Tôi sẽ đi Bắc Kinh thêm một lần nữa."],["李文","Lǐ Wén","为什么还去北京？","Wèishénme hái qù Běijīng?","Sao lại còn đi Bắc Kinh?"],["白家月","Bái Jiāyuè","因为我想再吃一次烤鸭，再喝一次奶茶，再去北京大学看一次电影……","Yīnwèi wǒ xiǎng zài chī yí cì kǎo yā, zài hē yí cì nǎichá, zài qù Běijīng Dàxué kàn yí cì diànyǐng… …","Vì tôi muốn ăn thêm một lần vịt quay, uống thêm một lần trà sữa, lại đến Đại học Bắc Kinh xem thêm một lần phim…"],["李文","Lǐ Wén","你想做的事情很多呀！","Nǐ xiǎng zuò de shìqing hěn duō ya!","Bạn muốn làm nhiều việc thật đấy!"],["白家月","Bái Jiāyuè","是呀，你看，我还在网上买好颐和园的门票了呢。","Shì ya, nǐ kàn, wǒ hái zài wǎngshàng mǎi hǎo Yíhéyuán de ménpiào le ne.","Đúng vậy, bạn xem, tôi còn mua sẵn vé Di Hòa Viên trên mạng rồi đấy."],["白家月","Bái Jiāyuè","我的高中同学就在颐和园上班，可以让他给你好好介绍介绍。","Wǒ de gāozhōng tóngxué jiù zài Yíhéyuán shàng bān, kěyǐ ràng tā gěi nǐ hǎo hǎo jièshào jièshào.","Bạn học cấp ba của tôi làm việc ngay ở Di Hòa Viên, có thể nhờ cậu ấy giới thiệu cho bạn thật kỹ."],["李文","Lǐ Wén","太好了！出门旅游，多个朋友多条路。","Tài hǎo le! Chūmén lǚyóu, duō ge péngyou duō tiáo lù.","Tuyệt quá! Đi du lịch, thêm một người bạn là thêm một con đường."]]},{"t":"Bài khóa 3 · Chuyến bay về nước","l":[["白家月","Bái Jiāyuè","李文，你有一年没回国了吧？","Lǐ Wén, nǐ yǒu yì nián méi huíguó le ba?","Lý Văn, bạn đã một năm chưa về nước rồi nhỉ?"],["李文","Lǐ Wén","不到一年。我六月的时候回去了一次。","Bú dào yì nián. Wǒ liù yuè de shíhou huíqù le yí cì.","Chưa đến một năm. Tháng Sáu tôi có về một lần."],["白家月","Bái Jiāyuè","我怎么忘了？还是我送你去的机场呢。","Wǒ zěnme wàng le? Háishi wǒ sòng nǐ qù de jīchǎng ne.","Sao tôi lại quên? Còn là tôi đưa bạn ra sân bay nữa chứ."],["李文","Lǐ Wén","是呀。","Shì ya.","Đúng vậy."],["白家月","Bái Jiāyuè","我记得你那次的机票很便宜。","Wǒ jìde nǐ nà cì de jīpiào hěn piányi.","Tôi nhớ vé máy bay lần đó của bạn rất rẻ."],["李文","Lǐ Wén","没错，可能因为那个时候去北京的人不多吧。","Méi cuò, kěnéng yīnwèi nàge shíhou qù Běijīng de rén bù duō ba.","Đúng thế, có lẽ vì lúc đó người đi Bắc Kinh không nhiều."],["白家月","Bái Jiāyuè","这次的机票虽然有点儿贵，但想到就要飞北京了，我还是很高兴的。","Zhè cì de jīpiào suīrán yǒudiǎnr guì, dàn xiǎng dào jiù yào fēi Běijīng le, wǒ háishi hěn gāoxìng de.","Vé máy bay lần này tuy hơi đắt, nhưng nghĩ đến sắp bay đi Bắc Kinh, tôi vẫn rất vui."]]}]};
